export interface QAItem {
  q: string;
  a: string;
  code?: string;
}

export interface QACategory {
  title: string;
  items: QAItem[];
}

export const qaCategories: QACategory[] = [
  {
    title: 'JavaScript Core',
    items: [
      { q: 'What is Thread of Execution?', a: 'The single "worker" that runs your JS code one line at a time, top to bottom. JS has exactly one, so while it is busy on a line, nothing else runs — no other function, no rendering. This is why a slow loop freezes the page.' },
      { q: 'What is an Execution Context?', a: 'The "box" JS creates to run a piece of code. It is built in two passes: first the memory pass scans and sets up all variables/functions (this is where hoisting happens), then the execution pass runs the code line by line. You get one Global context at startup and a new Function context for every function call, stacked on the call stack.' },
      { q: 'Difference between var, let, and const?', a: 'var is function-scoped and is already usable (as undefined) before its line — a common source of bugs. let and const are block-scoped ({} bounded) and throw if used before their line (the Temporal Dead Zone). const just means the variable cannot be reassigned; the object it points to can still be mutated. Rule of thumb: const by default, let when you must reassign, var never.', code: "console.log(a); // undefined - var exists early\nvar a = 5;\n\nconsole.log(b); // ReferenceError - let is in the TDZ until here\nlet b = 10;\n\nconst user = { name: \"A\" };\nuser.name = \"B\"; // OK - mutating, not reassigning\nuser = {};       // TypeError" },
      { q: 'What are closures?', a: 'When a function is created, it keeps a live link to the variables of the scope it was born in — even after that outer function has returned. So the inner function can still read and update those variables. That private, persistent state is what powers counters, once(), debounce/throttle, and module patterns.', code: "function makeCounter() {\n  let count = 0;               // private to this counter\n  return () => (count += 1);   // closes over `count`\n}\n\nconst a = makeCounter();\nconst b = makeCounter();\na(); a(); // 1, 2\nb();      // 1  - separate closure, separate count" },
      { q: 'What is hoisting?', a: 'During the memory pass, JS registers declarations before any code runs. function declarations are hoisted whole (callable before their line). var is hoisted but set to undefined. let/const are hoisted too but stay unusable until their line (TDZ). Nothing physically moves — the engine just learned the names first.', code: "greet();          // works - function declaration hoisted fully\nfunction greet() { console.log(\"hi\"); }\n\nconsole.log(x);   // undefined - var name known, value not yet\nvar x = 5;\n\nsayHi();          // TypeError - const holds a function, but TDZ\nconst sayHi = () => console.log(\"hi\");" },
      { q: 'Explain the Event Loop.', a: 'JS itself is single-threaded, but the browser/Node give it helpers (timers, network, etc.). When you call setTimeout or fetch, the helper does the waiting; when it is done, your callback is parked in a queue. The event loop is the checker that, once the call stack is empty, moves queued callbacks back onto the stack. Key rule: it fully drains the microtask queue (promises) before taking one macrotask (setTimeout).', code: "console.log(\"1\");                               // sync\nsetTimeout(() => console.log(\"2\"), 0);          // macrotask\nPromise.resolve().then(() => console.log(\"3\")); // microtask\nconsole.log(\"4\");                               // sync\n\n// 1, 4 (sync) -> 3 (microtask) -> 2 (macrotask)" },
      { q: 'What is a Promise?', a: 'An object that stands in for a value you do not have yet. It starts pending and settles once — either fulfilled (with a value) or rejected (with an error) — and never changes again. You attach .then/.catch to react when it settles. It exists to flatten nested callbacks into a readable chain and to give errors one place to land.', code: "function fetchUser(id) {\n  return new Promise((resolve, reject) => {\n    setTimeout(() => {\n      id > 0 ? resolve({ id, name: \"Rahul\" }) : reject(new Error(\"Invalid id\"));\n    }, 300);\n  });\n}\n\nfetchUser(1)\n  .then((user) => console.log(user))\n  .catch((err) => console.error(err.message));" },
      { q: 'What is the Virtual DOM?', a: 'A plain JS object tree that mirrors what the UI should look like. On each render React builds a fresh one, compares it to the previous tree (diffing), and then touches the real DOM only where they differ. The win is not that JS objects are magic — it is that batching many small changes into one minimal DOM update avoids slow, repeated layout/reflow.' },
      { q: 'Difference between null and undefined?', a: 'undefined = "JS has nothing here yet" — a declared-but-unassigned variable, a missing object property, a function with no return. null = "a developer deliberately put "nothing" here". Practical tell: undefined usually means you forgot something; null means you meant it. (Quirk: typeof null is "object", a historical bug.)', code: "let a;\nconsole.log(a);            // undefined - not assigned\nconsole.log({}.missing);   // undefined - no such key\n\nlet b = null;              // explicit \"empty\"\nconsole.log(b === null);   // true" },
      { q: 'Primitive vs non-primitive types?', a: 'Primitives (string, number, boolean, null, undefined, symbol, bigint) are copied by value — you get an independent copy. Objects/arrays/functions are copied by reference — the "copy" is just another label pointing at the same thing, so mutating through one label is visible through the other. This is behind most "why did my state change?" bugs.', code: "let a = 10, b = a; // value copy\nb = 20;\nconsole.log(a);    // 10 - untouched\n\nconst o1 = { x: 1 };\nconst o2 = o1;     // same object, new label\no2.x = 2;\nconsole.log(o1.x); // 2" },
      { q: 'Difference between map, filter, and forEach?', a: 'All three loop an array without mutating it. map returns a NEW array of the same length with each item transformed. filter returns a NEW, usually shorter array of the items that passed a test. forEach returns nothing — use it only for side effects (logging, pushing elsewhere). If you want a result array, never use forEach.', code: "const nums = [1, 2, 3, 4];\n\nnums.map((n) => n * 2);          // [2, 4, 6, 8]\nnums.filter((n) => n % 2 === 0); // [2, 4]\nnums.forEach((n) => save(n));    // undefined - side effect only" },
      { q: 'What is the "this" keyword?', a: '"this" is decided by HOW a function is called, not where it is written. Method call obj.fn() -> this is obj. Plain call fn() -> this is undefined (strict) or the global object. new Fn() -> this is the fresh object. call/apply/bind -> this is whatever you pass. Arrow functions have no own this — they use the this of the surrounding code, which is why they are safe inside callbacks.', code: "const user = {\n  name: \"Amit\",\n  greet() { console.log(this.name); },      // \"Amit\"\n  greetLater() {\n    setTimeout(function () { console.log(this.name); }, 0); // undefined\n    setTimeout(() => console.log(this.name), 0);            // \"Amit\"\n  },\n};" },
      { q: 'What is callback hell?', a: 'When each async step is nested inside the previous step\'s callback, the code drifts right into a "pyramid of doom" — hard to read, and error handling has to be repeated at every level. Promises let you chain steps flatly; async/await lets you write them as if they were sync, with one try/catch.', code: "// nested callbacks - hard to follow, errors handled per level\ngetUser(id, (u) => getPosts(u.id, (p) => getComments(p[0].id, (c) => render(c))));\n\n// async/await - linear, one catch\nasync function load() {\n  const u = await getUser(id);\n  const p = await getPosts(u.id);\n  render(await getComments(p[0].id));\n}" },
      { q: 'What is async/await?', a: 'A cleaner syntax over Promises. An async function always returns a Promise. await pauses just that function until the awaited Promise settles, then resumes with its value (or throws its error) — the main thread is NOT blocked, other code keeps running. Wrap awaits in try/catch for errors, and use Promise.all when awaits do not depend on each other.', code: "async function loadUser() {\n  try {\n    const user = await fetchUser(1); // function pauses here, thread does not\n    console.log(user);\n  } catch (err) {\n    console.error(err.message);       // catches a rejected promise\n  }\n}" },
      { q: 'Difference between asynchronous and synchronous?', a: 'Synchronous = each step blocks the next until it finishes; the thread waits. Asynchronous = you start a slow operation (network, timer, file) and move on; a callback/promise runs later when it completes. JS uses async so one slow request does not freeze the whole page or server.' },
      { q: 'What is optional chaining (?.)?', a: 'a?.b stops and returns undefined the moment a is null or undefined, instead of throwing "cannot read property of undefined". Great for deep/optional data (API responses, config). Pair it with ?? to supply a fallback. Do not overuse it to paper over data that should always exist — that hides real bugs.', code: "const user = { address: null };\n\nuser?.address?.city;            // undefined - no throw\nuser?.address?.city ?? \"N/A\";   // \"N/A\"\nuser.getName?.();               // safely calls only if it exists" },
      { q: 'What is destructuring?', a: 'A shorthand to pull values out of an array (by position) or an object (by key) into named variables in one line. Supports defaults, renaming, and nesting. Most common in React props, function parameters, and import-like unpacking.', code: "const user = { name: \"Amit\", age: 26, role: \"dev\" };\nconst { name, age = 18, role: title } = user; // default + rename\n\nconst [first, , third] = [10, 20, 30]; // skip the middle\n\nfunction greet({ name }) { return `Hi ${name}`; } // unpack a param" },
      { q: 'What is the spread operator (...)?', a: 'In a call or literal, ... expands an iterable/object into its individual pieces. Use it to make shallow copies and to merge — e.g. { ...state, name } produces a new object (React needs new references) with name overridden. Remember: shallow — nested objects are still shared.', code: "const merged = [...[1, 2], ...[3, 4]];        // [1, 2, 3, 4]\nconst next = { ...state, loading: false };    // new object, one field changed\nMath.max(...[5, 1, 9]);                        // 9 - array -> args" },
      { q: 'What is the rest operator (...)?', a: 'Same ... symbol, opposite job: in a function parameter or a destructuring pattern it COLLECTS the leftovers into a single array/object. rest gathers, spread scatters — context tells them apart.', code: "function sum(...nums) { return nums.reduce((a, n) => a + n, 0); }\nsum(1, 2, 3); // 6\n\nconst { id, ...rest } = { id: 1, a: 2, b: 3 }; // rest = { a: 2, b: 3 }" },
      { q: 'What are Higher-Order Functions?', a: 'A function that takes a function as an argument and/or returns a function. It lets you parameterize behavior. map/filter/reduce take a function; debounce/throttle/memoize and React HOCs return one. This is how you reuse logic (retry, logging, timing) by wrapping instead of copy-pasting.', code: "const withLogging = (fn) => (...args) => {\n  console.log(\"call\", args);\n  return fn(...args);\n};\n\nconst add = withLogging((a, b) => a + b);\nadd(2, 3); // logs \"call [2, 3]\", returns 5" },
      { q: 'What are decorators?', a: 'An @-syntax that wraps a class, method, or property to add behavior (logging, validation, dependency injection, route metadata) without editing the code inside. Under the hood a decorator is just a function that receives the target and returns a modified version. Heavily used in NestJS, Angular, and TypeORM; still a Stage 3 proposal in plain JS.', code: "function LogTime(target, key, descriptor) {\n  const original = descriptor.value;\n  descriptor.value = function (...args) {\n    console.time(key);\n    const r = original.apply(this, args);\n    console.timeEnd(key);\n    return r;\n  };\n}\n\nclass Api { @LogTime getUsers() { /* ... */ } }" },
      { q: 'What is prototypal inheritance?', a: 'Every JS object has a hidden [[Prototype]] link to another object; when you read a missing property, JS walks up this prototype chain until it finds it or hits null. Classes are sugar over this — methods live once on Constructor.prototype and are shared by all instances.', code: "function Animal(name) {\n  this.name = name;\n}\nAnimal.prototype.speak = function () {\n  return `${this.name} makes a sound`;\n};\n\nfunction Dog(name) {\n  Animal.call(this, name);                    // inherit instance props\n}\nDog.prototype = Object.create(Animal.prototype); // inherit methods\nDog.prototype.constructor = Dog;\n\nnew Dog(\"Rex\").speak(); // \"Rex makes a sound\" - found on Animal.prototype" },
      { q: 'Explain reduce, find, some, and every.', a: 'reduce boils an array down to a single value via an accumulator. find returns the first element matching a condition (or undefined). some returns true if at least one element passes. every returns true only if all elements pass.', code: "const nums = [1, 2, 3, 4];\n\nnums.reduce((acc, n) => acc + n, 0); // 10\nnums.find((n) => n > 2);            // 3\nnums.some((n) => n % 2 === 0);      // true\nnums.every((n) => n > 0);           // true" },
      { q: 'What is memoization?', a: 'Caching a function\'s output keyed by its arguments so repeated calls with the same input return instantly instead of recomputing — a space-for-time trade-off for pure, expensive functions.', code: "function memoize(fn) {\n  const cache = new Map();\n  return function (...args) {\n    const key = JSON.stringify(args);\n    if (cache.has(key)) return cache.get(key);\n    const result = fn.apply(this, args);\n    cache.set(key, result);\n    return result;\n  };\n}\n\nconst fastSquare = memoize((n) => n * n);" },
      { q: 'Difference between package.json and package-lock.json?', a: 'package.json lists your direct dependencies with version ranges (^, ~) plus project metadata and scripts. package-lock.json pins the exact resolved version of every package (including nested deps) so npm install produces an identical node_modules on every machine. Commit both.' },
      { q: 'Difference between typeof and instanceof?', a: 'typeof checks a PRIMITIVE type tag and returns a string ("string", "number", "object", "function"...) — it cannot tell arrays from objects (both are "object") and famously returns "object" for null. instanceof checks whether an object\'s prototype chain includes a given constructor\'s prototype — it works on objects/instances, not primitives, and breaks across different realms (iframes, vm contexts) because they have different prototype objects.', code: "typeof \"hi\";        // \"string\"\ntypeof [1, 2];      // \"object\" - arrays are objects\ntypeof null;         // \"object\" - historic bug\n\n[] instanceof Array;  // true\n[] instanceof Object;  // true - Array.prototype -> Object.prototype\n\"hi\" instanceof String; // false - primitive, not a String object" },
      { q: 'What are truthy and falsy values in JavaScript?', a: 'In a boolean context (if, ||, &&, ternary), every value is truthy except the 8 falsy ones: false, 0, -0, 0n, "", null, undefined, NaN. Everything else — including "0", "false" (strings), [], and {} — is truthy. Knowing the falsy list explains bugs like if (users.length) vs the common trap if ([]) which is always true.', code: "if (\"\") console.log(\"never\");   // falsy\nif ([]) console.log(\"runs\");    // truthy - empty array is still an object\nif (\"0\") console.log(\"runs\");   // truthy - non-empty string\nBoolean(document.all);          // false - the one documented exotic case" },
      { q: 'Why is 0.1 + 0.2 !== 0.3 in JavaScript?', a: 'JS numbers are IEEE-754 double-precision floats, which cannot represent most decimal fractions exactly in binary — 0.1 and 0.2 are already tiny approximations, and adding them compounds the error to 0.30000000000000004. Never compare floats with ===; compare the difference against a small epsilon, or work in integers (cents, not dollars) for money.', code: "0.1 + 0.2;                    // 0.30000000000000004\n0.1 + 0.2 === 0.3;             // false\n\nfunction almostEqual(a, b, eps = 1e-9) {\n  return Math.abs(a - b) < eps;\n}\nalmostEqual(0.1 + 0.2, 0.3);   // true" },
      { q: 'How do you correctly check for NaN?', a: 'NaN is the only JS value that is not equal to itself, so x === NaN always returns false — you cannot check it directly. Use Number.isNaN(x) (strict, no coercion) rather than the global isNaN(x), which coerces its argument first and wrongly flags things like isNaN("hello") as true for the wrong reason. Array.prototype.includes uses SameValueZero, so [NaN].includes(NaN) correctly returns true.', code: "NaN === NaN;              // false\nisNaN(\"hello\");            // true - coerces \"hello\" to NaN first\nNumber.isNaN(\"hello\");     // false - no coercion, correct\nNumber.isNaN(NaN);         // true\n[NaN].includes(NaN);       // true" },
      { q: 'What is an IIFE (Immediately Invoked Function Expression) and why use one?', a: 'A function defined and called in the same statement, wrapped in parentheses to force it to be parsed as an expression. It creates its own scope so internal variables don\'t leak into the surrounding/global scope — the classic way to avoid global namespace pollution before ES modules and block-scoped let/const existed. Still used today for one-off async setup at the top of a script, or to run an async function where top-level await isn\'t available.', code: "(function () {\n  const secret = 42; // not visible outside\n})();\n\n(async () => {\n  const data = await fetchConfig(); // IIFE to use await outside an async fn\n  init(data);\n})();" },
      { q: 'Difference between Object.freeze, Object.seal, and Object.preventExtensions?', a: 'preventExtensions blocks adding new properties, but existing ones can still be changed or deleted. seal does that plus blocks deleting existing properties (but their values can still be changed). freeze is the strictest — blocks adding, deleting, AND changing existing property values, making the object fully immutable at the top level. All three are shallow — a frozen object\'s nested object is still mutable.', code: "const o = { a: 1, nested: { b: 2 } };\nObject.freeze(o);\no.a = 99;          // silently fails (throws in strict mode)\no.nested.b = 99;   // works! freeze is shallow\ndelete o.a;        // fails\nObject.isFrozen(o); // true" },
    ],
  },
  {
    title: 'Async / Performance Patterns',
    items: [
      { q: 'What is debouncing?', a: 'Wait until the events STOP, then run once. Every new call cancels the pending timer and starts a fresh one, so the function only fires after a quiet gap. Use it for "final value" work: search-as-you-type (fire when they pause), resize-then-recalculate, autosave. Analogy: a lift that waits until people stop stepping in before closing.', code: "function debounce(fn, delay) {\n  let timer;\n  return function (...args) {\n    clearTimeout(timer);                       // cancel the previous plan\n    timer = setTimeout(() => fn.apply(this, args), delay);\n  };\n}\n\nconst onSearch = debounce((q) => fetchResults(q), 400);" },
      { q: 'What is throttling?', a: 'Run at most once per interval, no matter how many events fire in between — a rate limit. The function fires immediately, then ignores calls until the cooldown passes. Use it for "keep updating but not too often" work: scroll position, mouse-move, drag, firing analytics. Debounce = wait for silence; throttle = steady heartbeat.', code: "function throttle(fn, interval) {\n  let last = 0;\n  return function (...args) {\n    const now = Date.now();\n    if (now - last >= interval) {\n      last = now;\n      fn.apply(this, args);\n    }\n  };\n}\n\nwindow.addEventListener(\"scroll\", throttle(onScroll, 200));" },
    ],
  },
  {
    title: 'React',
    items: [
      { q: 'What are React Hooks?', a: 'Functions (names start with "use") that let a plain function component "hook into" React features — state (useState), side effects (useEffect), refs (useRef), context (useContext) — that used to require class components. They must be called at the top level, in the same order every render, so React can match each call to its stored value.' },
      { q: 'What is useState?', a: 'Gives a component a piece of memory that survives re-renders. It returns [value, setValue]; calling setValue schedules a re-render with the new value. State updates are async and batched, so when the next value depends on the previous one, pass a function to setValue instead of reading the current value directly.', code: "const [count, setCount] = useState(0);\n\nsetCount(count + 1); setCount(count + 1); // both see 0 -> ends at 1\nsetCount((c) => c + 1); setCount((c) => c + 1); // 0 -> 1 -> 2" },
      { q: 'What is useRef?', a: 'A box (ref.current) that persists across renders but does NOT trigger a re-render when you change it. Two uses: (1) grab a DOM node (<input ref={inputRef} />) to focus/measure it; (2) hold a mutable value between renders — a timer id, the previous prop, a "did this already run" flag — that the UI does not need to react to.', code: "function SearchInput() {\n  const inputRef = useRef(null);\n  useEffect(() => inputRef.current.focus(), []); // focus on mount\n  return <input ref={inputRef} />;\n}" },
      { q: 'What is useSelector?', a: 'A react-redux hook that reads a slice of the Redux store. You pass a selector function; the component re-renders only when the value that selector returns changes (compared with ===). Return the smallest thing you need, and use a memoized selector if you compute/derive an object or array, or you will re-render every dispatch.', code: "const itemCount = useSelector((s) => s.cart.items.length); // primitive - safe\nconst items = useSelector((s) => s.cart.items);            // reference - fine if not re-created" },
      { q: 'What is Redux-Saga?', a: 'Redux middleware for handling side effects (API calls, sequences, retries) as separate "saga" generator functions. Because generators pause and resume, sagas can be tested step by step and can be cancelled mid-flight (e.g. abort a search when a new one starts) — things redux-thunk cannot do cleanly. Most apps today use RTK Query or thunks and only reach for sagas on complex async flows.' },
      { q: 'Controlled vs uncontrolled components?', a: 'Controlled: React state is the single source of truth — the input shows value and every keystroke goes through onChange -> setState. You can validate, format, or disable typing. Uncontrolled: the DOM keeps the value itself; you only read it via a ref when needed (e.g. on submit). Controlled for anything interactive; uncontrolled for simple forms or file inputs.', code: "// controlled\nconst [v, setV] = useState(\"\");\n<input value={v} onChange={(e) => setV(e.target.value)} />;\n\n// uncontrolled\nconst ref = useRef(null);\n<input ref={ref} defaultValue=\"\" />; // read ref.current.value on submit" },
      { q: 'What is ref forwarding (forwardRef)?', a: 'A ref is not a normal prop, so it does not pass through a custom component to the DOM node inside it. forwardRef lets a component receive a ref and attach it to its inner element, so parents can focus/scroll/measure it. In React 19+, ref can be passed as a regular prop and forwardRef is no longer required.', code: "const FancyInput = React.forwardRef((props, ref) => (\n  <input ref={ref} className=\"fancy\" {...props} />\n));\n\n// parent can now do inputRef.current.focus()" },
      { q: 'What is lazy loading in React?', a: 'Split a component into its own JS chunk and download it only when it first renders, instead of shipping it in the initial bundle. React.lazy(() => import("./X")) returns a component; wrap it in <Suspense fallback={...}> to show something while the chunk loads. Best for routes, modals, heavy charts/editors — things not needed on first paint.', code: "const Dashboard = React.lazy(() => import(\"./Dashboard\"));\n\n<Suspense fallback={<Loader />}>\n  <Dashboard />\n</Suspense>" },
      { q: 'What are React Portals?', a: 'Render children into a DOM node somewhere else in the document (usually a top-level #modal-root) while keeping them in the same React tree — so context, state and event bubbling still work normally. Solves modals/tooltips/dropdowns getting clipped by a parent\'s overflow:hidden or trapped in a low z-index stacking context.', code: "import { createPortal } from \"react-dom\";\n\nfunction Modal({ children }) {\n  return createPortal(\n    <div className=\"modal\">{children}</div>,\n    document.getElementById(\"modal-root\")\n  );\n}" },
      { q: 'What is React Fiber?', a: 'React\'s rewritten internal engine (React 16+) that represents the work of rendering as a linked list of small units it can pause, resume, reprioritize, or throw away. That is what makes concurrent features possible — React can start rendering an update, notice a more urgent one (a keystroke), handle that first, then continue — so the UI stays responsive during big renders.' },
      { q: 'What is Reconciliation?', a: 'The process where React compares the newly rendered element tree with the previous one and works out the smallest set of real DOM changes to make. It uses heuristics: different element type -> replace the whole subtree; same type -> keep the node and update props; lists -> match children by key. Understanding it explains why keys and stable component types matter.' },
      { q: 'Why are keys important in lists?', a: 'A key is the stable identity React uses to track a list item across renders. With correct keys, reordering a list moves the existing DOM nodes (and their state, focus, animations). With array index as key, React thinks item 0 just changed its text — so state/inputs "stick" to the wrong row after a sort, insert, or delete. Use a real unique id from your data.', code: "{items.map((item, i) => <Row key={i} {...item} />)}   // bug on reorder\n{items.map((item) => <Row key={item.id} {...item} />)} // correct" },
      { q: 'useEffect dependency array — [], [dep], or none?', a: '[] -> run once after mount (setup: subscriptions, initial fetch). [a, b] -> run after mount and after any render where a or b changed (keep it in sync with those values). No array -> run after every render (almost always a mistake — usually an infinite loop). Whatever the effect reads from props/state should be in the array; the cleanup return runs before the next run and on unmount.', code: "useEffect(() => { const id = subscribe(); return () => unsubscribe(id); }, []);\nuseEffect(() => { fetchUser(userId); }, [userId]);" },
      { q: 'What is useMemo?', a: 'Caches the RESULT of a calculation between renders and only re-runs it when a dependency changes. Use it for genuinely expensive work (sorting/filtering a big list, heavy transforms) or to keep an object/array reference stable so a memoized child or another hook does not see a "new" value every render. Do not wrap cheap calculations — the caching itself has a cost.', code: "const sorted = useMemo(\n  () => [...items].sort((a, b) => a.price - b.price),\n  [items] // re-sorts only when items changes\n);" },
      { q: 'Difference between useCallback and React.memo?', a: 'React.memo wraps a component so it skips re-rendering when its props are shallow-equal to last time. useCallback keeps a function prop referentially stable between renders so that shallow check can pass (a fresh arrow function every render would always look "new"). They work as a pair: memo the child, useCallback/useMemo the props you pass it.', code: "const handleSelect = useCallback((id) => setSelected(id), []); // stable\nconst Row = React.memo(function Row({ onSelect }) { /* ... */ });" },
      { q: 'What are custom hooks?', a: 'A function whose name starts with "use" that calls other hooks to package reusable stateful logic — data fetching, form handling, a debounced value, media queries. It shares LOGIC, not state: each component that calls it gets its own independent state. This is how you avoid copy-pasting useEffect blocks across components.', code: "function useDebouncedValue(value, delay = 400) {\n  const [debounced, setDebounced] = useState(value);\n  useEffect(() => {\n    const t = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(t);\n  }, [value, delay]);\n  return debounced;\n}" },
      { q: 'Explain the component lifecycle.', a: 'Three phases: Mount (created and added to the DOM), Update (re-renders because its state, props, or a consumed context changed), Unmount (removed). In function components you do not use lifecycle methods — useEffect covers all three: the effect body runs on mount/update, and its returned cleanup runs on unmount (and before each re-run).' },
      { q: 'What is Redux?', a: 'A predictable state container. All shared state lives in one store; you never mutate it directly — you dispatch a plain action object, and a pure reducer function returns the next state. Because every change is an explicit, logged action, you get time-travel debugging and easy testing. Modern Redux = Redux Toolkit, which removes most of the boilerplate.' },
      { q: 'What is createSlice in Redux Toolkit?', a: 'One function that bundles a slice of state: its name, initial value, and reducers. From that it auto-generates the action types and action creators for you, so you never hand-write "cart/addItem" strings. It runs reducers through Immer, so you can write state.items.push(x) and it produces a correct new immutable state behind the scenes.', code: "const cartSlice = createSlice({\n  name: \"cart\",\n  initialState: { items: [] },\n  reducers: {\n    addItem: (state, action) => { state.items.push(action.payload); }, // Immer\n  },\n});\nexport const { addItem } = cartSlice.actions; // generated for you" },
      { q: 'What is dispatch in Redux?', a: 'The only way to change the store. You call dispatch(action) with a plain object describing what happened; Redux passes the current state and that action to your reducers, which return the next state, and subscribed components re-render. Think of it as "announce an event" — the reducer decides what that event does to state.', code: "dispatch(addItem({ id: 1, name: \"Shoes\" }));\n// -> cart reducer runs -> new state -> <Cart> re-renders" },
      { q: 'useReducer vs Redux — when to use which?', a: 'useReducer manages complex local state with a reducer function — no store, no middleware, scoped to one component/subtree. Redux is a global store shared app-wide, with devtools, middleware (thunk/saga), and a single source of truth. Reach for useReducer first; add Redux/Zustand only when many distant components need the same state.', code: "const [state, dispatch] = useReducer(reducer, { count: 0 });\n\nfunction reducer(state, action) {\n  switch (action.type) {\n    case \"inc\": return { count: state.count + 1 };\n    case \"reset\": return { count: 0 };\n    default: return state;\n  }\n}" },
      { q: 'What are Higher-Order Components (HOC)?', a: 'A function that takes a component and returns a new component with extra props/behavior injected — a pattern for reusing cross-cutting logic (auth, logging, data loading). Custom hooks are the modern replacement for most HOC use cases.', code: "function withAuth(Component) {\n  return function Guarded(props) {\n    const user = useUser();\n    if (!user) return <Redirect to=\"/login\" />;\n    return <Component {...props} user={user} />;\n  };\n}\n\nconst ProtectedDashboard = withAuth(Dashboard);" },
      { q: 'What is JSX, and how does it actually become a DOM update?', a: 'JSX is not HTML — it is syntax sugar that Babel/the compiler transforms into React.createElement(type, props, children) calls (or the newer automatic jsx() runtime), which produce plain JS objects (the Virtual DOM elements). Because it compiles to a function call, you can put any JS expression inside {} — but only one expression, and it must return something React can render.', code: "// what you write\nconst el = <h1 className=\"title\">Hi {name}</h1>;\n\n// what it compiles to\nconst el = React.createElement(\"h1\", { className: \"title\" }, \"Hi \", name);\n// -> { type: \"h1\", props: { className: \"title\", children: [...] } }" },
      { q: 'What is a React Fragment (<>...</>) and why use it?', a: 'React components must return a single root node. Wrapping siblings in a <div> just to satisfy that adds an extra, meaningless DOM element (which can break CSS grid/flex layouts expecting specific children). <React.Fragment> (or the <>...</> shorthand) groups elements without adding any real DOM node. Use the full <Fragment key={id}> form (not the shorthand) when you need a key, e.g. inside a list .map().' },
      { q: 'Why does React.StrictMode double-invoke component bodies and effects in development?', a: 'StrictMode intentionally renders components and re-runs effects (mount -> cleanup -> mount) TWICE in development only, to surface impure code — e.g. a component that mutates a module-level variable during render, or an effect whose cleanup does not fully undo its setup, which would silently break under future concurrent rendering. It never runs twice in production, and if your effect breaks under the double-run, that is the bug StrictMode was built to catch (usually a missing/incorrect cleanup function).' },
      { q: 'What is the children prop?', a: 'Whatever you place between a component\'s opening and closing tags is automatically passed to it as props.children — this is what makes generic wrapper components (Card, Modal, Layout) possible without hardcoding what goes inside them. It can be a string, an element, an array of elements, or a function (the "render props" pattern).', code: "function Card({ children }) {\n  return <div className=\"card\">{children}</div>;\n}\n\n<Card><h1>Title</h1><p>Body text</p></Card>; // children = [<h1>, <p>]" },
      { q: 'What are Synthetic Events in React?', a: 'React wraps the browser\'s native events in its own cross-browser SyntheticEvent object with a consistent API, and (pre-React 17) attached one listener at the document root and dispatched events through it for performance (React 17+ attaches to the root DOM container instead). You call e.preventDefault()/e.stopPropagation() the same way everywhere; access e.nativeEvent for the raw browser event if truly needed. In older React, the event object was pooled/reused after the handler returned — no longer the case since React 17.' },
      { q: 'Difference between defaultProps and JS default parameters?', a: 'Both supply a fallback when a prop is undefined, but default parameters (function Comp({ size = "md" })) work in both function and class components and are the modern standard; Component.defaultProps = {...} is the older static-property API, deprecated for function components in React 18.3+ (still works for class components). Prefer default parameters in new code.', code: "// modern - default parameter\nfunction Button({ size = \"md\", children }) { /* ... */ }\n\n// legacy - defaultProps (deprecated for function components)\nfunction Button({ size, children }) { /* ... */ }\nButton.defaultProps = { size: \"md\" };" },
    ],
  },
  {
    title: 'Node / Express / Backend',
    items: [
      { q: 'What is Node.js?', a: 'A runtime that lets you run JavaScript outside the browser (on the V8 engine), plus libraries for files, network, and processes. Its model is single-threaded + non-blocking: instead of one thread per request waiting on I/O, one thread starts many I/O operations and handles each result via a callback when it is ready. Great for I/O-heavy APIs; bad for CPU-heavy work (which blocks that one thread).' },
      { q: 'What is Express.js?', a: 'A thin web framework for Node: it gives you routing (map method + path to a handler) and a middleware pipeline, and stays out of your way for everything else. You assemble the app from small middleware functions. Newer alternatives (Fastify, NestJS) add speed or structure, but the mental model is the same.', code: "const app = require(\"express\")();\napp.use(express.json());\napp.get(\"/users/:id\", (req, res) => res.json({ id: req.params.id }));\napp.listen(3000);" },
      { q: 'What is Middleware?', a: 'A function with the signature (req, res, next) that sits in the request pipeline. It can read/modify req and res, then either call next() to pass control on, or end the request by sending a response. This is how cross-cutting concerns — logging, body parsing, auth, rate limiting, error handling — are layered without touching each route.', code: "function requireAuth(req, res, next) {\n  if (!req.headers.authorization) return res.status(401).json({ error: \"no token\" });\n  next(); // hand off to the next middleware / route\n}\napp.use(requireAuth);" },
      { q: 'How does middleware execution order work?', a: 'Express runs middleware in the exact order you register it, like a stack of layers the request passes through. Each layer must either call next() or send a response — forget both and the request hangs forever. Error-handling middleware (four args: err, req, res, next) is special and should be registered LAST so thrown errors fall through to it.', code: "app.use(logger);        // 1\napp.use(express.json()); // 2\napp.get(\"/me\", auth, handler); // 3: auth -> handler\napp.use(errorHandler);  // last: catches errors from all above" },
      { q: 'Difference between Authentication and Authorization?', a: 'Authentication = "who are you?" — proving identity (login, verifying a token/session). Authorization = "are you allowed to do this?" — checking permissions/roles/ownership AFTER identity is known. A logged-in user (authenticated) still gets 403 when deleting someone else\'s post (not authorized). Both must be enforced on the server, every request.' },
      { q: 'What is JWT?', a: 'JSON Web Token: a string of three base64 parts — header.payload.signature. The payload holds claims (user id, role, expiry); the signature is an HMAC/RSA sign of header+payload with your secret. On each request the server just verifies the signature and expiry — no DB/session lookup, which is why it scales. Trade-off: you cannot instantly revoke one (until it expires), so keep access tokens short-lived and use refresh tokens. Never put secrets in the payload — it is readable by anyone.', code: "const token = jwt.sign({ id: user.id, role: user.role }, SECRET, { expiresIn: \"15m\" });\nconst claims = jwt.verify(token, SECRET); // throws if tampered or expired" },
      { q: 'Why use Redis (and what does "indexing" mean here)?', a: 'Redis keeps data in RAM, so reads/writes are sub-millisecond. Common jobs: cache hot DB results, store sessions, rate-limit counters, queues (BullMQ), pub/sub, leaderboards (sorted sets). "Indexing" in Redis just means choosing the right data structure and key naming so a lookup is O(1) (hash/set) or O(log n) (sorted set) instead of scanning. It is a speed layer — your app must still work if Redis is down.' },
      { q: 'Difference between GET, POST, PUT, and PATCH?', a: 'GET = read, no body, safe (no side effects) and idempotent. POST = create / trigger an action, not idempotent (calling twice makes two things). PUT = replace the whole resource at a known URL, idempotent (same call = same end state). PATCH = partial update (send only changed fields). Idempotency matters because clients and proxies retry — GET/PUT/DELETE are safe to retry, POST is not.' },
    ],
  },
  {
    title: 'HTTP Status Codes',
    items: [
      { q: 'What are the 5 families of HTTP status codes?', a: 'The first digit is the category. 1xx informational (rare — "keep going"). 2xx success (200 OK, 201 Created, 204 No Content). 3xx redirection (301/302 moved, 304 Not Modified — use your cache). 4xx client error — the caller must change the request (400 bad, 401 no auth, 403 not allowed, 404 missing, 409 conflict, 422 validation, 429 rate limited). 5xx server error — the caller did nothing wrong (500 crash, 502/503/504 upstream/overload/timeout). Mnemonic: 4xx "you messed up", 5xx "we messed up".' },
      { q: 'Difference between 200, 201, and 204?', a: '200 OK — request succeeded, response has a body. 201 Created — a new resource was created (usually after POST), often returns the created resource. 204 No Content — request succeeded but there\'s no response body (common after DELETE/PUT).' },
      { q: 'Difference between 401 and 403?', a: '401 Unauthorized actually means "not authenticated" — no/invalid credentials. 403 Forbidden means you ARE authenticated but don\'t have permission to access that resource.' },
      { q: 'What is a 400 vs a 422 status code?', a: '400 Bad Request — the request itself is malformed (bad JSON, missing required field, wrong type). 422 Unprocessable Entity — the request is well-formed but fails validation/business rules (e.g., invalid email format, duplicate value).' },
      { q: 'What is a 409 Conflict used for?', a: 'Returned when a request conflicts with the current state of the resource — e.g., trying to create a user with an email that already exists, or a version/concurrency conflict on update.' },
      { q: 'What is a 429 status code?', a: 'Too Many Requests — the client has hit a rate limit; the response usually includes a Retry-After header telling the client when to try again.' },
      { q: 'Difference between 500, 502, and 503?', a: '500 Internal Server Error — generic unhandled server-side error. 502 Bad Gateway — a gateway/proxy got an invalid response from an upstream server. 503 Service Unavailable — server is temporarily down/overloaded (maintenance, restart, overload).' },
      { q: 'What is a 304 Not Modified used for?', a: 'Returned for conditional GET requests (using ETag/If-None-Match or Last-Modified headers) to tell the client its cached copy is still valid, saving bandwidth by not resending the body.' },
      { q: 'How do you decide which status code to send for a failed API call in your own backend?', a: '90% of the time a failure is the client\'s fault (4xx) — bad input (400/422), missing auth (401), no permission (403), not found (404), conflict (409). Only use 5xx when the failure genuinely happened on the server (DB down, unhandled exception, upstream service failed).' },
    ],
  },
  {
    title: 'JavaScript',
    items: [
      { q: 'How does event delegation work, and why is it efficient?', a: 'Events "bubble" up from the element clicked to its ancestors. So instead of putting a listener on every row, you put ONE on the parent and check e.target to see which child was hit. Wins: less memory (1 listener vs 1,000), and it automatically covers rows added later — no need to re-bind after rendering new items.', code: "list.addEventListener(\"click\", (e) => {\n  const row = e.target.closest(\"li\");   // handles clicks on inner spans too\n  if (row) select(row.dataset.id);\n}); // works for current AND future <li>s" },
      { q: 'Difference between == and ===? Explain type coercion.', a: '=== checks value AND type, no conversion. == first coerces the two sides to the same type using a set of quirky rules, then compares — so "5" == 5, 0 == false, and null == undefined are all true. Those rules cause bugs, so always use === (and !==). The one common exception: x == null is a handy shorthand for "null or undefined".', code: "\"5\" === 5;    // false\n\"5\" == 5;     // true  (string -> number)\n0 == \"\";      // true\n0 == false;   // true\nnull == undefined; // true" },
      { q: 'Deep copy vs shallow copy?', a: 'A shallow copy ({ ...obj }, Object.assign, slice) duplicates only the top level — nested objects/arrays are still the SAME references, so mutating obj.address.city also changes the original. A deep copy (structuredClone) recursively duplicates everything. structuredClone is the modern choice; JSON.parse(JSON.stringify(x)) works but drops Dates, functions, undefined, and Maps.', code: "const o = { name: \"A\", address: { city: \"Delhi\" } };\n\nconst shallow = { ...o };\nshallow.address.city = \"Mumbai\";\no.address.city; // \"Mumbai\" - shared!\n\nconst deep = structuredClone(o); // fully independent" },
      { q: 'Explain call(), apply(), and bind().', a: 'All three let you set "this" manually. call and apply invoke the function right now — call takes args one by one, apply takes them as an array (mnemonic: Apply = Array). bind does NOT invoke; it returns a NEW function with "this" (and optionally some args) locked in, to use later — e.g. passing a method as a callback without losing its object.', code: "function greet(g) { console.log(g, this.name); }\n\ngreet.call({ name: \"A\" }, \"Hi\");      // \"Hi A\" now\ngreet.apply({ name: \"A\" }, [\"Hi\"]);   // \"Hi A\" now\nconst h = greet.bind({ name: \"A\" });  // new fn\nsetTimeout(h, 100, \"Hey\");             // \"Hey A\" later" },
      { q: 'What is currying?', a: 'Rewriting f(a, b, c) so it can be called as f(a)(b)(c) — one argument at a time, each call returning a function that remembers the earlier args (via closure) until all are supplied. Its value is partial application: fix the first arg once and reuse the result, e.g. const log = curriedLogger("INFO") then log("saved").', code: "const curry = (fn) => {\n  const step = (...args) =>\n    args.length >= fn.length ? fn(...args) : (...rest) => step(...args, ...rest);\n  return step;\n};\n\nconst add = curry((a, b, c) => a + b + c);\nadd(1)(2)(3); // 6   ·   add(1, 2)(3); // 6" },
      { q: 'Difference between ?? (nullish coalescing) and || ?', a: '|| falls back when the left side is ANY falsy value: 0, "", false, NaN, null, undefined. ?? falls back only for null or undefined. So use ?? when 0 and "" are valid values you want to keep (counts, prices, empty strings) and || only when any falsy value should be replaced.', code: "const qty = 0;\nqty || 10;  // 10  - treats 0 as \"missing\" (bug if 0 is valid)\nqty ?? 10;  // 0   - keeps the real value\n\n\"\" ?? \"default\";  // \"\"\nundefined ?? \"x\"; // \"x\"" },
      { q: 'How does garbage collection work in JavaScript?', a: 'Memory is freed automatically. The engine starts from "roots" (global object, current call stack) and marks everything reachable by following references; whatever it cannot reach is garbage and gets swept. You do not free memory — but you can leak it by keeping references alive: forgotten timers/intervals, event listeners not removed, closures holding big objects, or an ever-growing cache/array.' },
      { q: 'setTimeout vs setImmediate vs process.nextTick (Node.js)?', a: 'process.nextTick() — runs right after the current operation finishes, before the event loop moves on (highest priority; overusing it can starve I/O). setImmediate() — runs in the "check" phase, i.e. after the current poll/I/O callbacks. setTimeout(fn, 0) — runs in the "timers" phase of the next loop turn. Ordering of setTimeout(0) vs setImmediate is not guaranteed at the top level, but inside an I/O callback setImmediate always wins.' },
      { q: 'Microtasks vs macrotasks — what\'s the difference?', a: 'Macrotasks: setTimeout, setInterval, setImmediate, I/O, UI events. Microtasks: Promise callbacks (.then/.catch/.finally), queueMicrotask, MutationObserver. After each macrotask the event loop drains the ENTIRE microtask queue before the next macrotask or a render — so promises always resolve before the next timer.', code: "console.log(\"start\");\nsetTimeout(() => console.log(\"timeout\"), 0);        // macrotask\nPromise.resolve().then(() => console.log(\"promise\")); // microtask\nconsole.log(\"end\");\n\n// start, end, promise, timeout" },
      { q: 'Spot the bug: `const score = fetchScore(); return score * 2;`', a: 'fetchScore() returns a Promise, not a number — Promise * 2 coerces to NaN. Fix: make the function async and await the promise (or chain .then). Forgetting await on an async call is one of the most common JS bugs.', code: "// broken\nfunction getUserScore() {\n  const score = fetchScore(); // a Promise, not 50\n  return score * 2;           // NaN\n}\n\n// fixed\nasync function getUserScore() {\n  const score = await fetchScore(); // 50\n  return score * 2;                 // 100\n}" },
    ],
  },
  {
    title: 'HTML & Web Fundamentals',
    items: [
      { q: 'Why does semantic HTML (<main>, <article>, <section>, <nav>) matter?', a: 'Semantic tags describe the meaning of content, not just its look. Screen readers use them as landmarks so users can jump between regions (main, nav, header), and search engines use them to understand page structure for SEO. <div>/<span> carry zero meaning — reserve them for styling hooks.', code: "<header>...</header>\n<nav>...</nav>\n<main>\n  <article>\n    <h1>Post title</h1>\n    <section>...</section>\n  </article>\n</main>\n<footer>...</footer>" },
      { q: 'Difference between <script>, <script defer>, and <script async>?', a: 'Plain <script> blocks HTML parsing while it downloads and runs. async downloads in parallel and runs as soon as it is ready (order not guaranteed) — good for independent scripts like analytics. defer downloads in parallel but runs after parsing, in document order — the best default for app scripts that need the DOM.' },
      { q: 'Difference between localStorage, sessionStorage, and cookies?', a: 'localStorage — ~5-10MB, persists until cleared, same-origin, never sent to the server. sessionStorage — same, but cleared when the tab closes. Cookies — ~4KB, sent with every HTTP request to the domain, can be HttpOnly/Secure/SameSite — use these for auth/session tokens, not the Web Storage APIs.' },
      { q: 'What is the CSS box model?', a: 'Every element is a box of content + padding + border + margin. With the default box-sizing: content-box, width/height size the content only, so padding/border add to the rendered size. box-sizing: border-box makes width/height include padding and border — far more predictable, which is why most resets apply it globally.', code: "*, *::before, *::after {\n  box-sizing: border-box;\n}" },
      { q: 'Event bubbling vs capturing?', a: 'When an event fires it first travels down from the root to the target (capture phase), then bubbles back up from the target to the root (bubble phase). Handlers run in the bubble phase by default; pass { capture: true } to listen on the way down. Bubbling is what makes event delegation possible.' },
      { q: 'How do you place 5 divs in a row without flex, margin, or padding?', a: 'Use display: inline-block on each div — they sit on one line like text but still accept width/height. The gotcha: whitespace between the tags in your HTML renders as a ~4px gap, so five 20%-wide boxes overflow and wrap. Fixes: remove the whitespace between tags, set font-size: 0 on the parent (and restore it on children), or use slightly smaller widths. In real projects prefer flexbox/grid — this question tests whether you understand inline vs block layout.', code: ".row { font-size: 0; }              /* kills the whitespace gap */\n.box { display: inline-block; width: 20%; height: 80px; font-size: 16px; }" },
    ],
  },
  {
    title: 'React / Next.js',
    items: [
      { q: 'Difference between useEffect and useLayoutEffect?', a: 'Both run after render, but timing differs. useLayoutEffect runs synchronously after React updates the DOM but BEFORE the browser paints — so you can measure an element and adjust layout with no visible flicker (the user never sees the intermediate frame). useEffect runs after paint, so a layout change there can flash. Default to useEffect; reach for useLayoutEffect only for measure-then-position work (tooltips, autosize). Note: useLayoutEffect blocks paint, so keep it fast.' },
      { q: 'What causes a React component to re-render?', a: 'Exactly four things: (1) its own state changed (setState), (2) a prop it receives changed, (3) its parent re-rendered (children re-render by default, even with unchanged props — unless wrapped in React.memo), (4) a context value it consumes changed. Note: mutating an object without changing its reference does NOT trigger a re-render — React compares by identity.' },
      { q: 'Context API vs Redux?', a: 'Context is a transport mechanism, not a state manager — it passes a value down without prop-drilling. Any change to the context value re-renders every consumer, so it fits low-frequency data (theme, current user, locale). Redux (or Zustand) is built for frequently-changing shared state: components subscribe to just the slice they use, so a cart update does not re-render the whole app. Rule of thumb: Context for "set once, read everywhere"; a store for "changes often, many readers".', code: "const ThemeContext = createContext(\"light\");\n\n<ThemeContext.Provider value={theme}>\n  <App />\n</ThemeContext.Provider>;\n\nconst theme = useContext(ThemeContext); // re-renders on ANY theme change" },
      { q: 'How would you implement protected routes using authentication?', a: 'Check auth status (token in cookie/localStorage or a context) before rendering a route; if not authenticated, redirect to login — in Next.js this is commonly done via middleware.js checking a cookie/JWT before the request reaches the page.', code: "// middleware.js\nexport function middleware(request) {\n  const token = request.cookies.get(\"token\");\n  if (!token && request.nextUrl.pathname.startsWith(\"/dashboard\")) {\n    return NextResponse.redirect(new URL(\"/login\", request.url));\n  }\n  return NextResponse.next();\n}\n\nexport const config = { matcher: [\"/dashboard/:path*\"] };" },
      { q: 'Difference between CSR, SSR, SSG, and ISR in Next.js?', a: 'Where and when the HTML is built. CSR: browser downloads a near-empty page, then JS fetches data and renders — fast deploys, slow first paint, weak SEO (dashboards). SSR: server builds the HTML fresh on every request — always current, costs server time per hit (feeds, personalized pages). SSG: HTML built once at build time and served as a static file — fastest, but stale until you rebuild (blogs, docs). ISR: SSG plus "rebuild this page in the background at most every N seconds" — static speed with periodic freshness (product listings).', code: "export const revalidate = 60; // ISR: re-generate at most once a minute\n\nexport default async function Products() {\n  const products = await fetch(API).then((r) => r.json());\n  return <ProductList products={products} />;\n}" },
      { q: 'How does Next.js App Router differ from the Pages Router?', a: 'Pages Router (pages/): every file is a client component by default; data fetching via getServerSideProps/getStaticProps at the page level; one flat layout via _app. App Router (app/): components are Server Components by default (zero JS shipped) and you opt into "use client"; nested co-located layout.tsx / loading.tsx / error.tsx; data fetched with async/await directly in components; streaming and Suspense built in. App Router is the current default for new apps.' },
      { q: 'Difference between ReactDOM.render() and createRoot() in React 18?', a: 'ReactDOM.render() was the legacy API (React 17 and earlier) for mounting an app. createRoot(container).render(<App/>) is the React 18 API that enables concurrent features like automatic batching, transitions, and Suspense improvements.', code: "// React 17\nReactDOM.render(<App />, document.getElementById(\"root\"));\n\n// React 18\nconst root = ReactDOM.createRoot(document.getElementById(\"root\"));\nroot.render(<App />);" },
      { q: 'What are Error Boundaries, and when would you use them?', a: 'A component that catches a JavaScript error thrown while rendering anywhere in its child tree, and shows a fallback UI instead of unmounting the whole app (React blanks the screen on an uncaught render error). Wrap independent sections — a widget, a route, a third-party embed — so one failing part does not take down the page. They catch render/lifecycle errors only: NOT event handlers, async code, or SSR (use try/catch there). Currently must be a class (or the react-error-boundary library).', code: "class ErrorBoundary extends React.Component {\n  state = { hasError: false };\n  static getDerivedStateFromError() { return { hasError: true }; }\n  componentDidCatch(err, info) { logError(err, info); }\n  render() { return this.state.hasError ? <Fallback /> : this.props.children; }\n}" },
      { q: 'How would you structure a large-scale React application?', a: 'Group by feature, not by file type — a /checkout folder holding its components, hooks, API calls and tests beats separate /components, /hooks, /api trees you jump between. Keep a shared /ui for dumb reusable components and /lib for helpers. Push data fetching into a hooks/services layer, keep business logic in custom hooks (components stay about markup), lazy-load routes, and enforce boundaries so features do not import each other\'s internals.' },
      { q: 'What are React Server Components (RSC)?', a: 'Components that run ONLY on the server (the default in the Next.js App Router). They can be async and talk straight to a database, filesystem, or secret-holding API, and they ship zero JavaScript to the browser — only the resulting HTML. The cost: no useState/useEffect/onClick and no browser APIs. For interactivity you add "use client" to a component, which then hydrates on the client. Pattern: server components for data + layout, small client components for the interactive leaves.', code: "// Server Component - no \"use client\"\nexport default async function Users() {\n  const users = await db.user.findMany(); // direct DB access, no API route\n  return <UserList users={users} />;\n}" },
      { q: 'What is idempotency, and which HTTP methods are idempotent?', a: 'A request is idempotent if making it once or making it ten times leaves the server in the same state. GET, PUT, DELETE are idempotent (deleting an already-deleted item is still "deleted"). POST and PATCH generally are not. It matters because networks retry: a timed-out POST that actually succeeded can double-charge a card — the fix is an idempotency key the server dedupes on.' },
      { q: 'What is CORS and why does it happen?', a: 'The browser\'s same-origin policy blocks JS on site A from reading responses from site B (different domain, port, or protocol) — this protects your logged-in sessions from malicious pages. CORS is the opt-in: the API at B sends Access-Control-Allow-Origin (and related) headers to say "A is allowed to read my responses". For non-simple requests the browser first sends an OPTIONS "preflight" to check. Key point: it is enforced by the browser, not the server — curl and mobile apps are unaffected.' },
      { q: 'How would you build a nested file/folder explorer?', a: 'One recursive <Node> component: a file renders as a leaf; a folder renders its name plus its children mapped through the same <Node>. Each folder holds its own open/closed state (useState), so expand/collapse is local and it handles infinite nesting with no depth logic.', code: "function Node({ node }) {\n  const [open, setOpen] = useState(false);\n  if (node.type === \"file\") return <div className=\"file\">{node.name}</div>;\n  return (\n    <div>\n      <div onClick={() => setOpen((o) => !o)}>\n        {open ? \"▾\" : \"▸\"} {node.name}\n      </div>\n      {open && node.children.map((child) => <Node key={child.id} node={child} />)}\n    </div>\n  );\n}" },
      { q: 'How do you debug and fix a memory leak in a React app?', a: 'Symptoms: memory climbs on navigation, app gets sluggish. Debug with Chrome DevTools > Memory (compare heap snapshots before/after a route change) and the Performance monitor. Common causes: timers/intervals/subscriptions/event listeners not cleaned up in useEffect, listeners re-added to window on every render, stale closures holding large objects, or setState after unmount. Fix: return a cleanup function from every useEffect that sets something up.', code: "useEffect(() => {\n  const id = setInterval(tick, 1000);\n  window.addEventListener(\"resize\", onResize);\n  return () => {\n    clearInterval(id);\n    window.removeEventListener(\"resize\", onResize);\n  };\n}, []);" },
      { q: 'How would you implement light/dark theming without performance issues?', a: 'Use CSS variables for colors and toggle a data-theme/class on <html> — the browser repaints via CSS with zero React re-render. Persist the choice in localStorage and set it in an inline script before first paint to avoid a flash. Don\'t put the theme value in a top-level Context that re-renders the whole tree on toggle.', code: ":root { --bg: #fff; --text: #111; }\n[data-theme=\"dark\"] { --bg: #0b0b0b; --text: #eee; }\nbody { background: var(--bg); color: var(--text); }\n\ndocument.documentElement.dataset.theme = next;\nlocalStorage.setItem(\"theme\", next);" },
      { q: 'How do you render large data tables with real-time updates performantly?', a: 'Virtualize rows (react-window / TanStack Virtual) so only visible rows mount. Memoize each row (React.memo) with referentially stable row data. Batch/throttle incoming socket updates (flush every 100-250ms) instead of setState per message. Use a stable key per row and keep sort/filter in a memoized selector or worker.', code: "const Row = React.memo(function Row({ row }) {\n  return <div className=\"row\">{row.name}: {row.value}</div>;\n});\n\nconst buffer = useRef([]);\nsocket.on(\"tick\", (u) => buffer.current.push(u));\nuseInterval(() => {\n  if (buffer.current.length) {\n    applyUpdates(buffer.current);\n    buffer.current = [];\n  }\n}, 150);" },
      { q: 'How do you ensure consistent rendering across browsers and devices?', a: 'Use a CSS reset/normalize, stick to well-supported CSS (check caniuse), let autoprefixer add vendor prefixes, prefer flexbox/grid over hacks, use feature detection (not UA sniffing) with graceful fallbacks, respect mobile safe-area insets, and test on real devices / BrowserStack. Lock it down with visual regression tests (Playwright / Chromatic).' },
      { q: 'A dashboard lags when users apply filters — how do you profile and optimize it?', a: 'Record with the React Profiler / Chrome Performance tab while filtering to see which components re-render and how long each commit takes. Typical fixes: memoize the derived/filtered data (useMemo), debounce the filter input, virtualize long result lists, wrap expensive children in React.memo, precompute an index for filtering, and use useTransition so the input stays responsive while results recompute.' },
    ],
  },
  {
    title: 'More React / Next.js',
    items: [
      { q: 'Why do hooks have rules (no conditionals/loops)?', a: 'React does not know hook names — it stores hook state in an array and matches each useState/useEffect to a slot purely by CALL ORDER. If a hook runs on render 1 but an if-statement skips it on render 2, every later hook shifts down a slot and reads the wrong state. So hooks must be called at the top level, unconditionally, in the same order every render. (Put the condition inside the hook, not around it.)' },
      { q: 'What is Zustand and how does it compare to Redux/Context?', a: 'A minimal global state library — no provider wrapping, no boilerplate actions/reducers, components subscribe to only the slice of state they use via a selector. Simpler than Redux, more scalable than Context for frequently-changing state.', code: "import { create } from \"zustand\";\n\nconst useCartStore = create((set) => ({\n  items: [],\n  addItem: (item) => set((state) => ({ items: [...state.items, item] })),\n}));\n\nfunction Cart() {\n  const items = useCartStore((state) => state.items); // re-renders only on items change\n}" },
      { q: 'What is list virtualization (windowing) and why use it?', a: 'A 10,000-row list creates 10,000 DOM nodes — huge memory, slow scroll, janky updates. Virtualization renders only the ~20 rows currently visible (plus a small buffer) and swaps their contents as you scroll, using a tall spacer to keep the scrollbar correct. Libraries: react-window, TanStack Virtual, @shopify/flash-list (RN). The catch: variable row heights and Cmd+F "find on page" need extra handling.' },
      { q: 'Why use React Query / SWR over useEffect + fetch?', a: 'Hand-rolled useEffect + fetch means you also hand-roll: caching, "don\'t refetch what we just fetched", refetch on window focus/reconnect, retries, request cancellation on unmount, loading/error state, and pagination. React Query / SWR give all of that, plus they treat server data as a cache (not app state) so multiple components asking for the same data share one request. Rule: server state -> a query library; UI state -> useState/Zustand.', code: "const { data, error, isLoading } = useQuery({\n  queryKey: [\"user\", id],\n  queryFn: () => fetchUser(id),\n}); // cached, deduped, refetched on focus, retried on failure" },
      { q: 'What does Next.js middleware run on, and what\'s it commonly used for?', a: 'It runs at the edge, before a request reaches a page or API route — commonly used for auth checks/redirects (e.g., blocking /dashboard without a token), header rewriting, and A/B testing/geolocation redirects.', code: "import { NextResponse } from \"next/server\";\n\nexport function middleware(request) {\n  const token = request.cookies.get(\"token\");\n  if (!token) return NextResponse.redirect(new URL(\"/login\", request.url));\n  return NextResponse.next();\n}\n\nexport const config = { matcher: [\"/dashboard/:path*\"] };" },
    ],
  },
  {
    title: 'Node / Backend (extra)',
    items: [
      { q: 'How do you handle errors in async Express route handlers?', a: 'Before Express 5, a rejected promise in an async handler is NOT caught by Express — it becomes an unhandledRejection and can crash the process. The fix: wrap handlers in a helper that catches the rejection and forwards it to next(err), so it lands in one central error-handling middleware (the 4-arg one, registered last) that decides the status code and response shape. Express 5 forwards async errors automatically, but the central handler pattern still applies.', code: "const wrap = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);\n\napp.get(\"/users/:id\", wrap(async (req, res) => {\n  const user = await User.findById(req.params.id);\n  if (!user) throw Object.assign(new Error(\"Not found\"), { status: 404 });\n  res.json(user);\n}));" },
      { q: 'How do you handle file uploads in Express?', a: 'Multipart/form-data is not JSON, so express.json() cannot parse it — you need a middleware like Multer that parses the stream and exposes req.file / req.files. In production do NOT save to the app server\'s disk: stream straight to object storage (S3), or better, have the client upload directly to S3 via a presigned URL and only send you the resulting key. Always validate size and real content type, not just the extension.', code: "const upload = multer({ limits: { fileSize: 5 * 1024 * 1024 } });\napp.post(\"/avatar\", upload.single(\"avatar\"), (req, res) => res.json({ key: req.file.key }));" },
      { q: 'How do you implement rate limiting in an API?', a: 'A middleware counts requests per key (IP, user id, or API key) within a rolling time window and returns 429 with a Retry-After header once the limit is passed. In-memory counters (express-rate-limit default) break across multiple server instances — use a shared store (Redis) so the limit is global. Common algorithms: fixed window (simple, allows bursts at edges), sliding window, or token bucket (smooths bursts). Put stricter limits on auth, search, and AI endpoints.', code: "const limiter = rateLimit({\n  windowMs: 15 * 60_000,\n  max: 100,\n  store: new RedisStore({ /* shared across instances */ }),\n});\napp.use(\"/api\", limiter);" },
      { q: 'What is the Node.js cluster module / worker_threads, and how do they differ?', a: 'Node runs your JS on ONE thread — a single instance cannot use more than one CPU core, no matter how much RAM/CPU the machine has. cluster forks multiple full copies of the process (each with its own event loop and memory) that share a listening port via round-robin — good for scaling a stateless HTTP server across cores (PM2 does this for you). worker_threads instead runs code on real OS threads WITHIN one process, sharing memory via SharedArrayBuffer/message-passing — better for offloading one CPU-heavy task (image processing, big JSON parsing) without blocking the main event loop, rather than duplicating the whole server.', code: "// cluster: N copies of the whole server across cores\nconst cluster = require(\"cluster\");\nif (cluster.isPrimary) {\n  for (let i = 0; i < require(\"os\").cpus().length; i++) cluster.fork();\n} else {\n  require(\"./server\"); // each worker runs the full app\n}" },
      { q: 'What are Streams in Node.js, and why use them over reading a whole file into memory?', a: 'A Stream processes data in small CHUNKS as it arrives, instead of loading the entire file/response into memory first — critical for large files (video, big CSV/exports) where fs.readFile would spike memory and delay the first byte sent. Four types: Readable (a source, e.g. file read), Writable (a destination, e.g. HTTP response), Duplex (both, e.g. a socket), Transform (reads, modifies, writes, e.g. gzip). .pipe() wires a Readable to a Writable and automatically handles backpressure (pausing the source if the destination can\'t keep up).', code: "const fs = require(\"fs\");\nconst zlib = require(\"zlib\");\n\n// streams a large file, compressing on the fly, low constant memory\nfs.createReadStream(\"huge.log\")\n  .pipe(zlib.createGzip())\n  .pipe(fs.createWriteStream(\"huge.log.gz\"));" },
      { q: 'What is database connection pooling, and why does it matter?', a: 'Opening a new DB connection (TCP handshake + auth) for every request is slow and can exhaust the database\'s max-connections limit under load. A connection pool opens a fixed number of connections up front and REUSES them: a request borrows a free connection, runs its query, and returns it to the pool instead of closing it. Drivers (Mongoose, pg, mysql2) pool by default — the main tuning knob is pool size, which should be sized to the DB\'s connection limit divided by the number of app instances, not left unbounded.' },
      { q: 'What are best practices for managing environment variables/config in a Node app?', a: 'Never commit secrets — keep them in .env (gitignored) locally and in the platform\'s secret manager (Vercel/AWS Secrets Manager/Docker secrets) in production. Validate required env vars at startup (fail fast with a clear error) rather than getting a cryptic undefined deep in the app later — libraries like zod or envalid do this well. Keep separate values per environment (dev/staging/prod), never reuse production secrets locally, and load them once at boot (process.env), not scattered ad hoc reads.', code: "import { z } from \"zod\";\n\nconst env = z.object({\n  DATABASE_URL: z.string().url(),\n  JWT_SECRET: z.string().min(32),\n  PORT: z.coerce.number().default(3000),\n}).parse(process.env); // throws immediately at startup if misconfigured" },
      { q: 'ORM (e.g. Mongoose/Prisma) vs raw SQL/queries — what are the trade-offs?', a: 'An ORM gives you schema validation, migrations, a typed/object-based query API, and protection from SQL injection by default — faster to build with and easier for a team to stay consistent. The cost: an abstraction layer can generate inefficient queries (the N+1 problem is common with careless ORM use), and very complex queries (multi-level aggregations, window functions) are often easier and faster to write as raw SQL. Common approach: use the ORM for standard CRUD, drop to raw queries/aggregation pipelines for reporting or performance-critical paths, and always parameterize raw queries — never string-concatenate user input into SQL.' },
    ],
  },
  {
    title: 'Databases',
    items: [
      { q: 'SQL vs MongoDB (NoSQL) — what is the difference?', a: 'SQL databases (MySQL, PostgreSQL) store data in tables with rows and columns under a fixed schema, relate tables via foreign keys + JOINs, and give strong ACID transactions. MongoDB stores flexible JSON-like documents (BSON) in collections — no fixed schema, related data can be embedded inside one document, and it scales out horizontally (sharding) more naturally. SQL = structured, relational, consistency-first. MongoDB = flexible, document-shaped, easy to scale and iterate on. Neither is "better" — it depends on the shape of your data and access patterns.', code: "-- SQL: fixed schema, data split across tables, joined at read time\nSELECT u.name, o.total\nFROM users u\nINNER JOIN orders o ON o.user_id = u.id\nWHERE u.id = 1;\n\n// MongoDB: one flexible document, related data embedded\n{\n  _id: 1,\n  name: \"Rishabh\",\n  orders: [ { total: 499 }, { total: 999 } ] // no JOIN needed\n}" },
      { q: 'Why do we use both SQL and MongoDB — why not just one?', a: 'Because they solve different problems, and real systems often mix them (polyglot persistence). Use SQL when data is highly relational and correctness matters — payments, orders, inventory, banking — where you need JOINs, constraints and ACID transactions. Use MongoDB when the schema changes often or varies per record — product catalogs, user profiles, CMS content, logs, real-time feeds — and you want fast development and easy horizontal scaling. Example: an e-commerce app keeps orders/payments in PostgreSQL (consistency), while the product catalog with varying attributes and activity logs live in MongoDB (flexibility). Rule of thumb: pick by data shape + consistency needs, not by trend. Note that modern MongoDB also supports multi-document transactions, and PostgreSQL supports JSON columns, so the gap is narrower than it used to be.' },
      { q: 'How does indexing improve database query performance?', a: 'Without an index the DB scans every row to find matches (O(n)). An index is a separate sorted structure (usually a B-tree) on one or more columns, so lookups become O(log n) — like the index at the back of a book vs reading every page. Cost: each write must also update the index, and indexes take disk/RAM. So index the columns you filter, join, and sort on — not every column. Verify with EXPLAIN that the query actually uses it.', code: "db.users.createIndex({ email: 1 }, { unique: true });\n// email lookup: full scan  ->  direct B-tree seek" },
      { q: 'What is an aggregation pipeline in MongoDB?', a: 'A conveyor belt: documents flow through ordered stages, each transforming the stream. $match filters, $group buckets and computes ($sum/$avg/$count), $sort orders, $lookup joins another collection, $project reshapes. Put $match and $limit as early as possible so later stages process fewer docs (and an early $match can use an index).', code: "Order.aggregate([\n  { $match: { status: \"completed\" } },        // filter first (uses index)\n  { $group: { _id: \"$userId\", spent: { $sum: \"$amount\" } } },\n  { $sort: { spent: -1 } },\n  { $limit: 10 },                              // top 10 spenders\n]);" },
      { q: 'How do you implement pagination in a database query?', a: 'Offset pagination (skip/limit or OFFSET) is simple but slow on deep pages — the DB still walks and discards all skipped rows — and can show duplicates/gaps if data changes between pages. Cursor (keyset) pagination remembers the last item\'s sort value and does WHERE created_at < lastSeen — O(log n) with an index, stable under inserts, but no random "jump to page 50". Use cursors for feeds and infinite scroll, offset for small admin tables.', code: "// cursor: fast + stable\nUser.find({ createdAt: { $lt: cursor } }).sort({ createdAt: -1 }).limit(20);" },
      { q: 'Difference between INNER JOIN and LEFT JOIN in SQL?', a: 'INNER JOIN keeps only rows that have a match on BOTH sides. LEFT JOIN keeps every row from the left table and fills right-side columns with NULL when there is no match. So "users who placed an order" is an INNER JOIN; "all users, with their order count (0 if none)" is a LEFT JOIN. A common bug: putting a right-table filter in the WHERE clause of a LEFT JOIN silently turns it back into an INNER JOIN (NULLs fail the filter).', code: "SELECT u.name, COUNT(o.id) AS orders\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nGROUP BY u.id; -- every user, even with 0 orders" },
      { q: 'Normalization vs denormalization?', a: 'Normalization stores each fact once, split across related tables — writes/updates are simple and consistent, but reads need joins. Denormalization deliberately duplicates data (e.g. store author_name on each post, not just author_id) so reads are a single fast lookup — at the cost of updating every copy when the source changes. Start normalized; denormalize specific hot read paths when profiling shows the joins hurt.' },
      { q: 'What are ACID properties in a database transaction?', a: 'Atomicity — a transaction\'s operations all succeed or all roll back, never half-applied (a money transfer either moves funds fully or not at all). Consistency — a transaction takes the DB from one valid state to another, never violating constraints/rules. Isolation — concurrent transactions don\'t see each other\'s uncommitted intermediate state (governed by isolation levels). Durability — once committed, data survives a crash (written to disk/WAL, not just memory). SQL databases guarantee ACID by default; many NoSQL databases relax some of these for scale/availability.', code: "BEGIN;\n  UPDATE accounts SET balance = balance - 100 WHERE id = 1;\n  UPDATE accounts SET balance = balance + 100 WHERE id = 2;\nCOMMIT; -- both updates succeed together, or neither does" },
      { q: 'What are database transaction isolation levels?', a: 'They control how much one transaction can see of another\'s in-progress changes, trading correctness for concurrency/speed. Read Uncommitted — can see other transactions\' uncommitted changes ("dirty reads"), fastest but dangerous, rarely used. Read Committed — only sees committed data, but a value can change between two reads in the same transaction ("non-repeatable read") — Postgres\'s default. Repeatable Read — the same row always reads the same value for the whole transaction, but new rows matching a query can still appear ("phantom read") — MySQL\'s default. Serializable — transactions behave as if run one at a time, strictest and slowest, used for financial-grade correctness.' },
      { q: 'Optimistic vs pessimistic locking — when do you use each?', a: 'Pessimistic locking grabs a lock on a row before touching it (SELECT ... FOR UPDATE), blocking other transactions until it releases — safe but hurts throughput and risks deadlocks; use it when conflicts are frequent and correctness is critical (seat/slot booking). Optimistic locking assumes conflicts are rare: read a row with its version number, and on write do UPDATE ... WHERE version = readVersion — if 0 rows were affected, someone else updated it first, so you retry or fail. Cheaper and more scalable; use it when conflicts are uncommon (most CRUD apps).', code: "// optimistic locking with a version column\nUPDATE products SET stock = stock - 1, version = version + 1\nWHERE id = 5 AND version = 3; -- 0 rows affected = someone else updated first, retry" },
      { q: 'What is the N+1 query problem, and how do you fix it?', a: 'Fetching a list (1 query), then looping over it and firing one more query PER item to get related data (N queries) — e.g. get 50 posts, then query each post\'s author separately: 51 queries instead of 2. Fix by eager-loading/joining upfront: .populate() in Mongoose, JOIN in SQL, or a DataLoader that batches per-tick requests into one query keyed by id. This is one of the most common real-world performance bugs, invisible until the list grows.', code: "// N+1 bug\nconst posts = await Post.find();\nfor (const post of posts) {\n  post.author = await User.findById(post.authorId); // N extra queries\n}\n\n// fixed - one extra query total (or a single join)\nconst posts = await Post.find().populate(\"authorId\");" },
      { q: 'What is a composite index, and does column order matter?', a: 'A composite index spans multiple columns, e.g. { status: 1, createdAt: -1 }, useful when queries filter/sort on that combination together. Order matters a lot: the index works left-to-right like a phone book sorted by (lastName, firstName) — you can efficiently search by lastName alone, or lastName+firstName, but NOT by firstName alone. Put the field used in equality filters (status: "active") before the field used in a range/sort (createdAt) for the index to serve both.', code: "db.orders.createIndex({ status: 1, createdAt: -1 });\n\n// uses the index (status is an equality prefix):\ndb.orders.find({ status: \"active\" }).sort({ createdAt: -1 });\n\n// does NOT use it efficiently (skips the status prefix):\ndb.orders.find({ createdAt: { $gt: someDate } });" },
      { q: 'How do you read a SQL query plan (EXPLAIN) and optimize a slow query?', a: 'Run EXPLAIN (or EXPLAIN ANALYZE in PostgreSQL/MySQL 8 to get real timings) to see how the DB executes the query. Red flags: Seq Scan / full table scan on a big table, a sort with no index, a huge gap between estimated and actual rows, nested loop over large sets. Fixes: add an index matching your WHERE / JOIN / ORDER BY columns (composite, in the right order), select only needed columns instead of SELECT *, avoid functions on indexed columns (WHERE LOWER(email) = ... defeats the index), replace OFFSET pagination with keyset pagination, fix N+1 queries, and keep table statistics fresh (ANALYZE). Always re-run EXPLAIN to confirm the plan changed to an Index Scan.', code: "EXPLAIN ANALYZE\nSELECT id, total FROM orders\nWHERE user_id = 42 AND status = 'paid'\nORDER BY created_at DESC LIMIT 20;\n-- Seq Scan on orders  -> slow\nCREATE INDEX idx_orders_user_status_created ON orders (user_id, status, created_at DESC);\n-- Index Scan using idx_orders_user_status_created -> fast" },
    ],
  },
  {
    title: 'System Design Basics',
    items: [
      { q: 'What are common caching strategies in a web app?', a: 'Cache at every layer the data can safely live: browser (HTTP cache headers), a query library (React Query), a CDN for static assets and cacheable pages near the user, an app-level in-memory cache, and a shared cache (Redis) for hot DB reads. The pattern is usually cache-aside: check cache -> miss -> read DB -> write to cache with a TTL. The hard part is invalidation — knowing when a cached value is stale (TTL, or explicitly bust it on write).' },
      { q: 'Difference between vertical and horizontal scaling?', a: 'Vertical = bigger box (more CPU/RAM). Zero code changes, but there is a ceiling and it is a single point of failure. Horizontal = more boxes behind a load balancer. No ceiling and redundant, but your app must be stateless — no session or upload sitting in one server\'s memory, because the next request may hit a different box. Move that state to Redis / a DB / object storage first, then scale out.' },
      { q: 'How would you design a URL shortener at a high level?', a: 'Core: a store mapping short_code -> long_url. Generate the code by base62-encoding an auto-increment id (guaranteed unique, no collision check) or by hashing + checking. Reads massively outnumber writes, so cache hot codes in Redis and serve redirects from there; return 301/302 to the long URL. Record click analytics asynchronously (push an event to a queue) so it never slows the redirect. Scale reads with replicas/cache; the write path is tiny.' },
      { q: 'How would you scale a MERN app to thousands of concurrent users?', a: 'Scaling is removing bottlenecks layer by layer, not just adding servers. Frontend: CDN for static assets, code splitting, fix re-renders. API: multiple stateless Node instances behind a load balancer, Redis for hot reads, rate limiting. DB: indexes, query tuning, read replicas, shard if needed. Heavy work: push to a queue (Kafka / BullMQ) and process in background workers.', code: "React -> CDN -> Load Balancer -> Node instances -> Redis -> MongoDB\n                                      |\n                          Queue -> Background Workers" },
      { q: 'What are the common bottlenecks in a MERN app under load?', a: 'React — unnecessary re-renders and large bundles. Node — blocking / CPU-heavy work stalling the event loop. MongoDB — missing indexes and inefficient queries. APIs — repeated uncached requests. Infra — a single backend instance with no load balancing. Fix each at its own layer.' },
      { q: 'What is the CAP theorem?', a: 'In a distributed system that has a network partition (a P — nodes can\'t talk to each other, which WILL eventually happen), you must choose between Consistency (every read gets the latest write, but the system may refuse requests until it can guarantee that) and Availability (every request gets a response, but it might be stale data). You cannot have all three (C, A, P) at once during a partition — P is not optional in the real world, so the real trade-off is C vs A. Example: a bank balance leans CP (better to refuse than show wrong money); a social media like-count leans AP (a slightly stale count is fine, always respond).' },
      { q: 'What are common load balancing algorithms?', a: 'Round robin — requests go to each server in turn, simple but ignores server load. Least connections — sends the next request to whichever server currently has the fewest active connections, better for uneven request durations. IP hash / consistent hashing — the same client (or key) always routes to the same server, useful for session stickiness or cache locality. Weighted versions of any of these account for servers with different capacity (a bigger box gets a higher weight = more traffic).' },
      { q: 'What are the common rate-limiting algorithms, and how do they differ?', a: 'Fixed window — count requests in a clock-aligned window (e.g. per minute); simple, but allows a burst of 2x the limit right at the window boundary. Sliding window log — stores every request timestamp and counts how many fall in the last N seconds; accurate but memory-heavy at scale. Sliding window counter — approximates the sliding log cheaply by weighting the previous and current fixed windows; the practical default (used by many API gateways). Token bucket — a bucket refills with tokens at a steady rate and each request consumes one; allows controlled bursts up to the bucket size while enforcing a long-term average rate — this is why it\'s the most common choice for public APIs.' },
      { q: 'Difference between database replication and sharding?', a: 'Replication copies the SAME full dataset onto multiple servers (a primary that accepts writes, replicas that serve reads) — it improves read throughput and gives failover/redundancy, but every replica still holds all the data, so it doesn\'t help once the dataset itself is too big or writes are too heavy for one primary. Sharding SPLITS the dataset across servers by a shard key (e.g. userId range or hash) — each shard holds only a slice of the data, so both storage and write load scale horizontally, at the cost of cross-shard queries/joins becoming expensive or impossible. Large systems typically combine both: shard for scale, replicate each shard for availability.' },
      { q: 'What does "at-least-once" vs "exactly-once" vs "at-most-once" delivery mean for a message queue?', a: 'At-most-once — a message might be lost but is never redelivered (fire-and-forget, no ack tracking) — fine for metrics/logs where losing a few is okay. At-least-once — the broker retries until it gets an ack, so a message may be delivered more than once if the ack is lost after processing — the common default (Kafka, SQS); your consumer MUST be idempotent (safe to process the same message twice) to use it safely. Exactly-once is the hardest and most expensive to guarantee end-to-end (usually achieved via idempotency keys/dedup tables on top of at-least-once delivery, not as a free broker feature).' },
      { q: 'Kafka vs RabbitMQ — when do you choose which?', a: "Kafka is a distributed, append-only LOG: messages are retained (for days or forever), split into partitions with ordering per partition, and consumer groups can replay from any offset. It gives very high throughput and suits event streaming, analytics pipelines, event sourcing and CDC. RabbitMQ is a traditional MESSAGE BROKER: producers publish to exchanges that route (direct/topic/fanout) to queues, messages are pushed to consumers and deleted after ack. It suits task queues, complex routing, request/reply and lower-volume workloads. Rule of thumb: 'a stream of events many consumers may re-read' → Kafka; 'jobs to be worked once' → RabbitMQ." },
      { q: 'WebSocket vs SSE vs (long) polling — which one for a live feed or stock ticker?', a: 'Polling: client asks every N seconds — simplest, works everywhere, but wasteful and delayed. Long polling: server holds the request open until data arrives — better latency, still one request per message. SSE (Server-Sent Events): one-way server → client stream over plain HTTP with built-in auto-reconnect and Last-Event-ID — ideal for tickers, notifications, order status. WebSocket: full-duplex, low-overhead persistent connection — needed when the client also sends frequent messages (chat, multiplayer, collaborative editing). Stock ticker → SSE (or WebSocket if you need subscribe/unsubscribe messages); always add reconnect with backoff and a polling fallback.' },
      { q: 'How would you design a Swiggy-style restaurant page with live order tracking?', a: "Split by how the data changes. Restaurant + menu are read-heavy and rarely change → CDN + Redis cache, SSR/ISR for SEO and fast first paint. Availability/price/offers change often → fetch client-side separately and cache briefly. Live order status → SSE (one-way updates) or WebSocket, fed by an event-driven backend: order events go through Kafka/queue to status and notification services. Rider location → frequent small updates, throttled on the client and rendered on a map. Client concerns: optimistic UI, reconnect with backoff, resume from the last event id, and a polling fallback. Mention idempotent order placement and how you'd handle a failed payment." },
    ],
  },
  {
    title: 'DSA Essentials',
    items: [
      { q: 'What is the two-pointer technique?', a: 'Instead of a nested loop checking every pair (O(n²)), you keep two indices and move them toward each other (or in the same direction) based on the current state — one pass, O(n). Works when the array is sorted or when the problem is about pairs/subarrays: pair-sum, reverse in place, remove duplicates, container-with-most-water, merging two sorted arrays.', code: "function hasPairWithSum(sorted, target) {\n  let lo = 0, hi = sorted.length - 1;\n  while (lo < hi) {\n    const sum = sorted[lo] + sorted[hi];\n    if (sum === target) return true;\n    sum < target ? lo++ : hi--;   // too small -> raise low; too big -> lower high\n  }\n  return false;\n}" },
      { q: 'What is the sliding window technique?', a: 'For "best/longest/shortest contiguous subarray or substring" problems. Instead of re-checking every window from scratch (O(n²) or worse), you keep a window [start..end], grow end one step at a time, and shrink start only when the window breaks a rule — each index enters and leaves once, so O(n). The window state (a sum, a char count map) is updated incrementally, not recomputed.', code: "function longestUnique(s) {\n  const lastSeen = new Map();\n  let start = 0, best = 0;\n  for (let end = 0; end < s.length; end++) {\n    if (lastSeen.get(s[end]) >= start) start = lastSeen.get(s[end]) + 1;\n    lastSeen.set(s[end], end);\n    best = Math.max(best, end - start + 1);\n  }\n  return best;\n}" },
      { q: 'Why use a HashMap for lookups in DSA problems?', a: 'A HashMap/Set gives O(1) average "have I seen this?" and "what value maps to this key?". That lets you replace an inner loop with a single lookup — the classic move that turns an O(n²) brute force into O(n) by spending O(n) memory. Two Sum, group-anagrams, first-non-repeating-char, subarray-sum-equals-k all use it.', code: "function twoSum(nums, target) {\n  const seen = new Map(); // value -> index\n  for (let i = 0; i < nums.length; i++) {\n    if (seen.has(target - nums[i])) return [seen.get(target - nums[i]), i];\n    seen.set(nums[i], i);\n  }\n}" },
      { q: 'What is memoization, and how does it help recursion like Fibonacci?', a: 'Naive recursive fib(n) recomputes the same subproblems exponentially — fib(50) makes ~2^50 calls. Memoization caches each fib(k) the first time it is computed, so every later call is an O(1) lookup. That collapses the work to O(n) (one entry per k). It is the top-down form of dynamic programming; the bottom-up form fills an array iteratively.', code: "function fib(n, memo = {}) {\n  if (n <= 1) return n;\n  if (n in memo) return memo[n];\n  return (memo[n] = fib(n - 1, memo) + fib(n - 2, memo));\n}\n// O(2^n)  ->  O(n)" },
      { q: 'What are the common Big-O time complexities, from fastest to slowest?', a: 'O(1) constant — array index access, hash map get/set. O(log n) logarithmic — binary search, balanced BST operations (halving the problem each step). O(n) linear — a single loop over the input. O(n log n) — efficient sorting (merge sort, quicksort average case), or a loop containing a binary search. O(n²) quadratic — nested loops over the same input (naive pair-finding, bubble sort). O(2^n) exponential — naive recursive Fibonacci, generating all subsets. O(n!) factorial — generating all permutations. Interviewers care less about naming it and more about you spotting a nested loop or repeated work and improving it.' },
      { q: 'BFS vs DFS — when do you use which?', a: 'Both visit every node/vertex of a graph or tree, but in different order. BFS (queue-based) explores level by level — use it for shortest path in an UNWEIGHTED graph, and anything about "minimum steps/hops" (word ladder, shortest path in a maze). DFS (stack/recursion-based) dives as deep as possible before backtracking — use it for exploring all paths, detecting cycles, topological sort, and problems naturally expressed as "try this, then try that" (maze solving, connected components, tree traversals). Space: BFS can hold an entire level in the queue (wide graphs are expensive); DFS is bounded by the depth of recursion.', code: "function bfs(graph, start) {\n  const visited = new Set([start]);\n  const queue = [start];\n  while (queue.length) {\n    const node = queue.shift();\n    for (const next of graph[node]) {\n      if (!visited.has(next)) { visited.add(next); queue.push(next); }\n    }\n  }\n}\n\nfunction dfs(graph, node, visited = new Set()) {\n  if (visited.has(node)) return;\n  visited.add(node);\n  for (const next of graph[node]) dfs(graph, next, visited);\n}" },
      { q: 'Recursion vs iteration — what are the trade-offs?', a: 'Recursion often reads closer to the problem\'s natural definition (tree traversal, divide-and-conquer, backtracking) — but each call adds a stack frame, so a deep recursion (e.g. over 10,000+ elements without tail-call optimization, which JS engines generally don\'t implement) can throw "Maximum call stack size exceeded". Iteration (a loop, or recursion converted to an explicit stack/queue) uses constant or controlled extra space and avoids that limit, at the cost of sometimes messier code for inherently recursive problems like tree recursion. Rule of thumb: recursion for trees/graphs/backtracking where depth is bounded and small; iteration (or memoized/bottom-up DP) when input size could be large.' },
      { q: 'What is a Trie, and when would you use one?', a: 'A tree where each node represents one character, and a path from the root spells out a prefix/word — shared prefixes share the same nodes. It answers "does this prefix exist?" or "insert/search a word" in O(word length), independent of how many words are stored, which a plain array/hash set of strings cannot do efficiently for PREFIX queries. Used for autocomplete/typeahead, spell-checkers, and IP routing tables (longest prefix match).', code: "class TrieNode { children = {}; isEnd = false; }\n\nclass Trie {\n  root = new TrieNode();\n  insert(word) {\n    let node = this.root;\n    for (const ch of word) node = (node.children[ch] ??= new TrieNode());\n    node.isEnd = true;\n  }\n  startsWith(prefix) {\n    let node = this.root;\n    for (const ch of prefix) {\n      if (!node.children[ch]) return false;\n      node = node.children[ch];\n    }\n    return true;\n  }\n}" },
      { q: 'Greedy vs Dynamic Programming — how do you tell which a problem needs?', a: 'Greedy makes the locally best choice at each step and never reconsiders it, which only produces the globally optimal answer when the problem has the "greedy choice property" (e.g. coin change with standard denominations, interval scheduling, Dijkstra\'s shortest path) — it\'s fast (usually O(n log n) from a sort) but WRONG on problems without that property (e.g. coin change with arbitrary denominations). Dynamic Programming instead explores overlapping subproblems and combines their best results, guaranteeing the optimal answer whenever a greedy pick could be wrong later — the cost is more time/space (typically O(n·target) for a DP table) because it considers possibilities greedy would skip. Quick test: try a small counterexample for the greedy approach — if picking "locally best" now can paint you into a worse corner later, you need DP.' },
      { q: 'Binary search — how does the pattern extend beyond a sorted array?', a: "Binary search works on ANY monotonic condition: 'is the answer ≤ x?' flips from false to true exactly once. So you can search the ANSWER SPACE: minimum eating speed (Koko bananas), ship capacity in D days, integer square root, first/last occurrence, search in a rotated array. Template: lo/hi bounds, compute mid = lo + ((hi - lo) >> 1) to avoid overflow, and move whichever side can't contain the answer. Complexity O(log n) × the cost of the check.", code: "// smallest x in [lo, hi] for which ok(x) is true\nfunction lowerBound(lo, hi, ok) {\n  while (lo < hi) {\n    const mid = lo + ((hi - lo) >> 1);\n    if (ok(mid)) hi = mid;      // mid works, try smaller\n    else lo = mid + 1;          // mid fails, need bigger\n  }\n  return lo;\n}\n// Koko: lowerBound(1, max(piles), (k) => hoursNeeded(piles, k) <= h)" },
      { q: "DFS template on a grid — 'Number of Islands'", a: "Scan every cell; when you find unvisited land ('1'), count one island and run DFS/BFS to mark the entire connected region as visited (here by sinking it to '0'). Each cell is visited once, so O(rows × cols) time. Same skeleton solves flood fill, max area of island, surrounded regions and connected components — recognize 'connected region in a grid/graph' as DFS/BFS.", code: "function numIslands(grid) {\n  const rows = grid.length, cols = grid[0].length;\n  let count = 0;\n  const dfs = (r, c) => {\n    if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] !== '1') return;\n    grid[r][c] = '0';                         // mark visited\n    dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1);\n  };\n  for (let r = 0; r < rows; r++)\n    for (let c = 0; c < cols; c++)\n      if (grid[r][c] === '1') { count++; dfs(r, c); }\n  return count;\n}" },
      { q: "How do you approach a Dynamic Programming problem — what are 'state transitions'?", a: "Follow four steps: (1) define the STATE — what does dp[i] (or dp[i][j]) mean in plain words; (2) write the TRANSITION — how a state is built from smaller states; (3) set BASE cases; (4) pick the evaluation order. Start with recursion + memoization (top-down) since it's easier to derive, convert to a bottom-up table, then shrink the space if only the last row/few values are needed. Example — Coin Change: dp[a] = fewest coins to make amount a; transition dp[a] = min(dp[a - coin] + 1) over all coins; base dp[0] = 0.", code: "function coinChange(coins, amount) {\n  const dp = Array(amount + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let a = 1; a <= amount; a++)\n    for (const c of coins)\n      if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);\n  return dp[amount] === Infinity ? -1 : dp[amount];\n}\nconsole.log(coinChange([1, 2, 5], 11)); // 3  (5 + 5 + 1)" },
    ],
  },
  {
    title: 'Bonus (Git, Docker, Testing, Deployment)',
    items: [
      { q: 'Difference between git rebase and git merge?', a: 'Both bring another branch\'s changes into yours. merge adds a "merge commit" that ties the two histories together — non-destructive, keeps the true timeline, but history becomes a web. rebase re-writes your commits so they sit on top of the latest target branch — a clean straight line, easier to read/bisect, but it changes commit hashes, so never rebase commits you have already pushed and others have pulled. Common flow: rebase your local feature branch to stay current, merge it into main via PR.' },
      { q: 'Difference between a Docker image and a container?', a: 'An image is a read-only, layered snapshot of a filesystem + the command to run — built from a Dockerfile, versioned, shareable (like a class). A container is a running (or stopped) instance of an image with its own writable layer and isolated process/network (like an object). One image -> many containers.', code: "# Dockerfile builds the image\nFROM node:20-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nCMD [\"node\", \"server.js\"]\n# docker run <image>  ->  a container" },
      { q: 'Difference between unit, integration, and E2E tests?', a: 'Unit: one function/component in isolation, dependencies mocked — fast, run in the hundreds. Integration: several real pieces together (route + service + a test database) — catches wiring bugs mocks hide. E2E: a real browser driving the deployed app through a full user journey (login -> checkout) — highest confidence, slowest and flakiest. The "testing pyramid": many unit, some integration, few E2E on the critical paths.', code: "test(\"increments on click\", () => {\n  render(<Counter />);\n  fireEvent.click(screen.getByRole(\"button\", { name: \"+\" }));\n  expect(screen.getByText(\"1\")).toBeInTheDocument();\n});" },
      { q: 'What is a basic CI/CD setup for a web app?', a: 'CI (Continuous Integration): on every push/PR a pipeline runs install -> lint -> typecheck -> tests -> build. A red pipeline blocks the merge, so main is always in a working state. CD (Continuous Delivery/Deployment): on merge to main it builds one artifact/image and deploys it (often to a staging env first, then production) — ideally with a health check and automatic rollback. Goal: catch problems before users do, and make releases boring.' },
    ],
  },
  {
    title: 'Accessibility / WCAG',
    items: [
      { q: 'What is WCAG?', a: 'Web Content Accessibility Guidelines — a W3C standard defining how to make web content accessible to people with disabilities, organized around 4 principles (POUR): Perceivable, Operable, Understandable, Robust, with 3 conformance levels (A, AA, AAA — AA is the common legal/industry target).' },
      { q: 'Why is accessibility important?', a: 'Ensures people with visual, motor, auditory, or cognitive disabilities can use your app (ethical + often legal requirement, e.g. ADA/Section 508); it also improves SEO, keyboard usability, and overall UX for everyone.' },
      { q: 'How do you make a React app accessible?', a: 'Use semantic HTML (button, nav, header) instead of divs with click handlers, add proper labels for form inputs, ensure keyboard navigation (tab order, focus states, no keyboard traps), manage focus on route/modal changes, use ARIA attributes only when semantic HTML isn\'t enough, and maintain sufficient color contrast.' },
      { q: 'What are ARIA attributes?', a: 'Accessible Rich Internet Applications attributes (aria-label, aria-hidden, aria-live, role, etc.) that add accessibility info to elements for screen readers when native HTML semantics aren\'t enough — e.g., aria-label="Close" on an icon-only button. Rule of thumb: prefer native semantic HTML first, use ARIA only to fill gaps.' },
      { q: 'What is keyboard navigation and why does it matter?', a: 'The ability to operate an entire app using only the keyboard (Tab, Enter, Esc, arrow keys) — critical for users who can\'t use a mouse (motor disabilities) or screen reader users. Requires visible focus indicators and a logical tab order.' },
      { q: 'What is the difference between aria-hidden and display: none / visibility: hidden?', a: 'display:none/visibility:hidden removes an element visually and from the accessibility tree (screen readers skip it too). aria-hidden="true" hides an element only from assistive tech/screen readers while it stays visually present — used to hide purely decorative content (icons) from screen readers.', code: "<button aria-hidden=\"true\">🔔</button>\n<!-- visually present, but skipped by screen readers -->\n\n<button style=\"display: none\">🔔</button>\n<!-- removed visually AND from the accessibility tree -->" },
      { q: 'How do you test accessibility?', a: 'Automated tools (Lighthouse, axe DevTools, eslint-plugin-jsx-a11y) catch common issues (missing alt text, contrast, labels), but manual testing — keyboard-only navigation and a real screen reader (VoiceOver/NVDA) — is needed to catch what automated tools miss.' },
    ],
  },
  {
    title: 'Performance Optimization',
    items: [
      { q: 'What techniques have you used to optimize a React/Next.js app?', a: 'Memoization (React.memo/useMemo/useCallback) to avoid unnecessary re-renders, code splitting/lazy loading routes and heavy components, image optimization (next/image), list virtualization for long lists, debouncing/throttling expensive handlers, caching API responses (SWR/React Query), and minimizing bundle size (tree-shaking, analyzing bundle with next-bundle-analyzer).' },
      { q: 'Where have you used React.memo(), useMemo() & useCallback()?', a: 'React.memo — wrapping a pure child component that re-renders often due to a frequently-updating parent, but whose own props rarely change. useMemo — memoizing an expensive computation (e.g., filtering/sorting a large list) so it only recalculates when its dependencies change. useCallback — memoizing a function passed as a prop to a React.memo\'d child, or as a dependency to another hook (useEffect), so it doesn\'t get a new reference on every render.', code: "const Row = React.memo(function Row({ item, onSelect }) {\n  return <li onClick={() => onSelect(item.id)}>{item.name}</li>;\n});\n\nconst sorted = useMemo(() => [...items].sort(byPrice), [items]);\nconst handleSelect = useCallback((id) => setSelected(id), []);" },
      { q: 'How do you fix unnecessary re-renders?', a: 'First measure with the React Profiler — do not guess. Then, in rough order of impact: move state DOWN to the smallest component that needs it (a re-render only affects that subtree); split unrelated state so a text input does not re-render a chart; pass primitives not freshly-built objects/arrays as props; wrap genuinely expensive children in React.memo and stabilise their props with useMemo/useCallback; use a store with selectors (Zustand/Redux) so components subscribe only to their slice. Note: a re-render is not automatically a problem — a cheap one is fine.' },
      { q: 'What is lazy loading & code splitting?', a: 'Code splitting breaks the JS bundle into smaller chunks instead of one large file. Lazy loading loads a chunk (route, component, or library) only when it\'s actually needed — e.g., React.lazy() + Suspense for components, or Next.js\'s automatic per-route code splitting — reducing the initial bundle size and load time.', code: "const Dashboard = React.lazy(() => import(\"./Dashboard\"));\n\n<Suspense fallback={<Loader />}>\n  <Dashboard />\n</Suspense>" },
      { q: 'What other frontend performance techniques do you know?', a: 'Compressing/lazy-loading images (next/image, WebP), minimizing/deferring third-party scripts, using a CDN for static assets, reducing layout shifts (CLS) by reserving space for images/ads, prefetching routes/data on hover/viewport entry, and enabling gzip/brotli compression + HTTP caching headers.' },
      { q: 'How do you measure frontend performance?', a: 'Core Web Vitals — LCP (Largest Contentful Paint, loading speed), FID/INP (Interactivity), CLS (Cumulative Layout Shift, visual stability) — measured via Lighthouse, Chrome DevTools Performance tab, or real-user monitoring (Web Vitals library, Vercel Analytics).' },
      { q: 'How do you optimize backend/API performance?', a: 'DB indexing on frequently queried fields, pagination instead of returning huge datasets, caching hot reads in Redis, using projection to fetch only needed fields, avoiding N+1 queries (batch/populate properly), and compressing responses (gzip).' },
      { q: 'What are Core Web Vitals, and how do you explain them to non-technical stakeholders?', a: 'LCP (Largest Contentful Paint) — how fast the main content appears ("how quickly the page looks ready"). INP (Interaction to Next Paint) — how snappy taps/clicks feel ("does it respond when I click"). CLS (Cumulative Layout Shift) — how much the layout jumps ("does stuff move under my finger"). Plus FCP (first pixel) and TTI (fully interactive). Frame it as user experience, conversions and SEO ranking — not milliseconds.' },
      { q: 'How do you debug a slow API response?', a: 'Measure where the time goes — add timing logs / APM spans around DB calls, external calls and serialization. Check the query plan (.explain() / EXPLAIN ANALYZE) for missing indexes or full scans, look for N+1 queries, oversized payloads, missing caching, blocking sync work on the event loop, or a slow upstream dependency. Then fix that specific bottleneck: index, cache, paginate, parallelize awaits, or move heavy work to a job.' },
      { q: "How would you reduce a React app's initial page load time by 40%?", a: 'Measure first — Lighthouse, WebPageTest and a bundle analyzer tell you whether the problem is JS size, images, fonts, or slow API/server time. Then attack the biggest items: route-based code splitting with React.lazy/dynamic import; drop or replace heavy libraries (moment → date-fns) and rely on tree shaking; optimize images (WebP/AVIF, correct sizes, lazy loading, next/image); preload critical fonts with font-display: swap; SSR/SSG the above-the-fold content; serve through a CDN with Brotli compression and long-lived cache headers; defer or lazy-load third-party scripts; and preconnect/prefetch critical requests. Re-measure after each change so you can prove the 40% with numbers (LCP, TTI, bundle size).' },
      { q: 'How do you optimize a Next.js app (SSR, code splitting, images, caching)?', a: 'Pick the right rendering per page — SSG/ISR for mostly-static content, SSR only when data must be fresh per request. Use Server Components to keep JS off the client, and next/dynamic for heavy client-only widgets (routes are code-split automatically). Use next/image (responsive sizes, lazy loading, modern formats) and next/font (self-hosted, no layout shift). Caching: fetch cache with revalidate or tags, on-demand revalidation, CDN caching for static assets and ISR pages. Stream slow sections with Suspense/loading.js, prefetch links with next/link, load third-party code via next/script with the right strategy, and check the bundle with @next/bundle-analyzer.' },
    ],
  },
  {
    title: 'Agile',
    items: [
      { q: 'What is a Sprint & Sprint Planning?', a: 'A Sprint is a fixed, short time-box (commonly 1-2 weeks) in which a team delivers a working increment of the product. Sprint Planning is the meeting at the start of the sprint where the team picks items from the product backlog, estimates them, and commits to a sprint goal/scope.' },
      { q: 'What is a Daily Stand-up?', a: 'A short (~15 min) daily meeting where each team member answers: what I did yesterday, what I\'ll do today, and any blockers — keeps the team aligned and surfaces blockers early, not a status report to a manager.' },
      { q: 'What is Sprint Review & Retrospective?', a: 'Sprint Review — held at the end of the sprint, the team demos completed work to stakeholders and gathers feedback. Sprint Retrospective — a team-only meeting right after, reflecting on what went well, what didn\'t, and what process changes to make next sprint.' },
      { q: 'What are Story Points & Definition of Done?', a: 'Story Points estimate the relative effort/complexity/uncertainty of a task (not raw hours), often using Fibonacci-like scales (1, 2, 3, 5, 8...), agreed on via team discussion (e.g., planning poker). Definition of Done is the team\'s shared checklist a task must meet to be considered truly complete (code reviewed, tested, deployed to staging, docs updated, etc.) — prevents "done" from meaning different things to different people.' },
      { q: 'What is a Product Backlog vs a Sprint Backlog?', a: 'The Product Backlog is the full, prioritized list of all desired work for the product (features, bugs, tech debt), owned/prioritized by the Product Owner. The Sprint Backlog is the subset of backlog items pulled into the current sprint, plus the plan to deliver them.' },
      { q: 'What roles exist in Scrum?', a: 'Product Owner (owns the backlog, prioritizes based on business value), Scrum Master (facilitates the process, removes blockers, protects the team from disruption), and the Development Team (cross-functional, self-organizing, delivers the work).' },
      { q: 'Difference between Scrum and Kanban?', a: 'Scrum works in fixed time-boxed sprints with defined roles/ceremonies and a sprint commitment. Kanban is a continuous flow model with no fixed iterations — work items move through columns (To Do → In Progress → Done) with a WIP (work-in-progress) limit, and priorities can shift anytime.' },
      { q: 'What is a User Story?', a: 'A short description of a feature from an end user\'s perspective, typically in the format "As a [user], I want [goal], so that [benefit]" — kept small enough to fit within a sprint and paired with acceptance criteria defining when it\'s complete.' },
      { q: 'What is backlog grooming/refinement?', a: 'An ongoing activity (often a recurring meeting) where the team reviews, clarifies, estimates, and reprioritizes upcoming backlog items so they\'re "ready" (well-defined, estimated, small enough) before they\'re pulled into a sprint.' },
    ],
  },
  {
    title: 'TypeScript',
    items: [
      { q: 'What is TypeScript and why use it over plain JavaScript?', a: 'A layer on top of JavaScript that adds type annotations checked at compile time, then erased — the browser runs plain JS. Value: the compiler catches "cannot read property of undefined", wrong argument types, and typos before you run the code; the editor gives real autocomplete and safe rename/refactor; and the types double as always-accurate documentation. The cost is a build step and some upfront typing effort, which pays off on any codebase more than one person touches.' },
      { q: 'Difference between interface and type in TypeScript?', a: 'Both describe shapes. interface can be extended/re-opened (declaration merging), preferred for object/class contracts. type is more flexible (unions, intersections, primitives) but can\'t be merged after declaration.', code: "interface User { name: string; age: number }\ninterface User { email: string } // merges with the one above\n\ntype Point = { x: number; y: number };\ntype Id = string | number; // unions - only type can do this" },
      { q: 'Difference between any and unknown?', a: 'any turns off type checking completely. unknown also accepts any value but forces you to narrow/check its type before using it — safer default when the type is genuinely not known yet.', code: "let a: any = 5;\na.toUpperCase(); // no error, but crashes at runtime\n\nlet b: unknown = 5;\nb.toUpperCase(); // compile error - must narrow first\nif (typeof b === \"string\") b.toUpperCase(); // ok" },
      { q: 'What are generics in TypeScript?', a: 'A way to write reusable functions/components that work with multiple types while keeping type safety, e.g. function identity<T>(arg: T): T — the type is inferred/specified per call instead of hardcoded.', code: "function identity<T>(arg: T): T {\n  return arg;\n}\n\nidentity<string>(\"hello\"); // T = string\nidentity(42);              // T inferred as number" },
    ],
  },
  {
    title: 'Microservices',
    items: [
      { q: 'What is a microservices architecture, and the trade-off vs a monolith?', a: 'The app is split into small services, each owning its own data and deployable on its own. Gains: teams ship independently, you scale only the hot service, one crash need not take down everything, and services can use different tech. Costs: a network call (with its latency and failures) replaces a function call, no more cross-table transactions, plus you now run service discovery, tracing, versioned contracts, and more infra. Rule: start with a well-structured "modular monolith" and split out a service only when a real pressure (team size, independent scaling, deploy cadence) demands it.' },
      { q: 'How do microservices communicate?', a: 'Two styles. Synchronous — one service calls another\'s REST or gRPC endpoint and waits; simple, but couples them (if B is down, A fails) and adds latency that compounds across a chain. Asynchronous — a service publishes an event to a broker (Kafka, RabbitMQ, SQS) and others react on their own time; more resilient and decoupled, but now the flow is eventually consistent and harder to trace. Use sync for "I need the answer now", async for "tell others this happened".' },
    ],
  },
  {
    title: 'AWS / Docker / CI-CD',
    items: [
      { q: 'What is AWS S3 typically used for in a full stack app?', a: 'Object storage for static files/uploads (images, documents, PDFs) — the app uploads to a bucket and serves files via a URL/CDN instead of storing them on the app server\'s disk.' },
      { q: 'What is AWS EC2?', a: 'A virtual server (compute instance) used to host and run your backend app, giving full control over the OS/runtime — contrast with serverless (Lambda), where you don\'t manage the server at all.' },
      { q: 'What is Docker Compose used for?', a: 'Defining and running a multi-container setup (e.g., app + MongoDB + Redis) from a single docker-compose.yml with one command, instead of starting/networking each container manually.', code: "# docker-compose.yml\nservices:\n  app:\n    build: .\n    ports: [\"3000:3000\"]\n  mongo:\n    image: mongo\n  redis:\n    image: redis" },
      { q: 'What does a typical CI/CD pipeline in GitHub Actions do?', a: 'A workflow YAML triggered on push/PR that installs dependencies, runs lint + tests, builds the app, and (on merge to main) deploys automatically — catching regressions before they reach production.', code: "# .github/workflows/ci.yml\non: [push, pull_request]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: npm install\n      - run: npm test\n      - run: npm run build" },
    ],
  },
  {
    title: 'Redis Caching',
    items: [
      { q: 'How is Redis typically used for caching (cache-aside pattern)?', a: 'On a read, check Redis first; on a cache miss, fetch from the DB, store the result in Redis with a TTL, then return it. Later reads hit Redis directly until it expires or is invalidated on the next write.', code: "async function getUser(id) {\n  const cached = await redis.get(`user:${id}`);\n  if (cached) return JSON.parse(cached);\n\n  const user = await db.user.findById(id);\n  await redis.set(`user:${id}`, JSON.stringify(user), \"EX\", 3600);\n  return user;\n}" },
    ],
  },
  {
    title: 'API Docs / Payments / Security',
    items: [
      { q: 'What is Swagger / OpenAPI used for?', a: 'OpenAPI is a standard format (YAML/JSON) that describes every endpoint of a REST API — paths, methods, params, request/response schemas, auth. From that one file you get: interactive docs (Swagger UI) where people try calls in the browser, generated typed client SDKs, request/response validation, and contract tests. Best practice is to make the spec the source of truth and generate code/docs from it, not write it by hand afterwards.' },
      { q: 'What is a webhook, and how do Stripe webhooks work?', a: 'A webhook is an HTTP callback — Stripe sends a POST request to your server when an event happens (payment succeeded/failed/refunded). You verify the signature, then update your DB/order status based on that event, since it\'s the reliable server-to-server source of truth.', code: "app.post(\"/webhook\", express.raw({ type: \"application/json\" }), (req, res) => {\n  const event = stripe.webhooks.constructEvent(req.body, req.headers[\"stripe-signature\"], secret);\n  if (event.type === \"payment_intent.succeeded\") {\n    markOrderPaid(event.data.object.id);\n  }\n  res.json({ received: true });\n});" },
      { q: 'Why shouldn\'t you confirm a payment using only the client-side response?', a: 'The browser tab can close, the network can drop, or the client can be tampered with — the webhook (server-to-server) is the only guaranteed confirmation that the payment actually succeeded.' },
      { q: 'How do you design RBAC (role-based access control) with multiple roles like Admin/Organization/User?', a: 'Store the role (and permissions if needed) on the user/JWT payload, check it in middleware before granting access to a route, and always enforce it server-side — never trust a role/permission flag sent from the client.' },
    ],
  },
  {
    title: 'Be Ready to Explain — Your Projects (likely follow-up questions)',
    items: [
      { q: 'Walk me through how you implemented JWT + RBAC across 3 live platforms.', a: 'Cover: JWT issued at login with role embedded in the payload, a verifyToken middleware on protected routes, a requireRole middleware restricting endpoints per role (admin/manager/staff/customer), and why role checks must live server-side to prevent privilege escalation.' },
      { q: 'How did you reduce page load times by 40% through MongoDB indexing and query optimization?', a: 'Cover: identifying slow queries (e.g., via .explain()), adding indexes on frequently filtered/sorted fields, using projection to fetch only needed fields, and paginating large result sets instead of loading everything.' },
      { q: 'How did you integrate Stripe end-to-end (checkout, webhooks, confirmation) with zero failed-transaction disputes?', a: 'Cover: creating a Checkout Session/PaymentIntent on the backend, listening for the payment_intent.succeeded webhook to confirm payment server-side (not just the client redirect), updating booking/order status only after webhook confirmation, and handling idempotency so a retried webhook doesn\'t double-process.' },
      { q: 'How did you design the loyalty rewards engine (formula builder with fixed/percentage toggle)?', a: 'Cover: storing the reward rule (type + value) per business in MongoDB, calculating the actual reward amount server-side after payment confirmation (never trust a client-calculated value), and crediting it asynchronously so it doesn\'t block the checkout response.' },
      { q: 'How did you keep booking state in sync in real time across the customer app and admin calendar?', a: 'Be ready to say which approach you used — polling/refetch on interval, WebSockets/Socket.io push updates, or optimistic UI with server reconciliation — and why (e.g., to prevent showing a slot as available after someone else just booked it).' },
      { q: 'How would you prevent double-booking of the same slot under concurrent requests?', a: 'Cover: a unique index on (resource, slot, date) at the DB level, or an atomic findOneAndUpdate that checks-and-sets the slot\'s status in one operation, so two simultaneous requests can\'t both succeed.' },
      { q: 'How did you structure 3 interconnected apps (admin dashboard, customer marketplace, REST API server) sharing Mongoose models?', a: 'Cover: a single REST API server as the source of truth with shared Mongoose schemas, and two separate Next.js frontends (admin + marketplace) consuming that same API — keeping data shape consistent across apps.' },
      { q: 'What\'s your workflow going from a Figma design to a deployed feature within a 2-week sprint?', a: 'Cover: breaking the design into components, agreeing the API contract with the backend early, building UI against mock data in parallel, wiring up real API calls, then QA against the design before merging.' },
    ],
  },
  {
    title: 'JavaScript Deep Dive',
    items: [
      { q: 'How would you polyfill Array.prototype.map, filter, reduce, or Function.prototype.bind?', a: 'Reimplement each with a plain for loop: map/filter call the callback with (element, index, array) and collect results; reduce accumulates into a single value; bind returns a new function that calls the original with a fixed `this` plus any pre-bound arguments.', code: "Array.prototype.myMap = function (callback) {\n  const result = [];\n  for (let i = 0; i < this.length; i++) result.push(callback(this[i], i, this));\n  return result;\n};\n\nFunction.prototype.myBind = function (context, ...boundArgs) {\n  const fn = this;\n  return function (...args) {\n    return fn.apply(context, [...boundArgs, ...args]);\n  };\n};" },
      { q: 'Difference between Promise.all, Promise.allSettled, Promise.race, and Promise.any?', a: 'all waits for every promise and rejects fast on the first rejection. allSettled waits for all and never rejects, returning a status per promise. race settles as soon as the first promise settles, resolve or reject. any resolves as soon as the first one fulfills, ignoring rejections until all reject.', code: "const results = await Promise.allSettled([fetchUser(1), fetchUser(-1)]);\n// [{status: \"fulfilled\", value: {...}}, {status: \"rejected\", reason: Error}]\n\nawait Promise.all([p1, p2]);   // rejects fast if any one rejects\nawait Promise.race([p1, p2]);  // settles as soon as the first settles\nawait Promise.any([p1, p2]);   // resolves on first fulfillment" },
      { q: 'What\'s the classic var vs let closure gotcha in a setTimeout loop?', a: 'With var (function-scoped), every callback shares the same variable and logs the final value (3, 3, 3). With let (block-scoped), each iteration gets its own binding, so callbacks log the value at that iteration (0, 1, 2).', code: "for (var i = 0; i < 3; i++) {\n  setTimeout(() => console.log(i), 100); // 3, 3, 3\n}\n\nfor (let j = 0; j < 3; j++) {\n  setTimeout(() => console.log(j), 100); // 0, 1, 2\n}" },
      { q: 'How do you remove duplicates or group an array of objects by a key?', a: 'Dedupe primitives with [...new Set(arr)]. Group objects by a key using reduce — build an accumulator object where each key maps to an array of matching items (a "groupBy" pattern).', code: "const unique = [...new Set([1, 2, 2, 3, 3, 3])]; // [1, 2, 3]\n\nfunction groupBy(arr, key) {\n  return arr.reduce((acc, item) => {\n    const group = item[key];\n    acc[group] = acc[group] || [];\n    acc[group].push(item);\n    return acc;\n  }, {});\n}" },
      { q: 'How does the `new` keyword work internally, step by step?', a: 'Four steps happen behind `new Fn(args)`: (1) a brand-new empty object is created, (2) its internal [[Prototype]] is linked to Fn.prototype (so it can find inherited methods), (3) Fn is called with `this` bound to that new object, (4) if Fn explicitly returns its own object, that is used instead — otherwise the new object from step 1 is returned automatically. This is exactly what Object.create + call replicates.', code: "function myNew(Fn, ...args) {\n  const obj = Object.create(Fn.prototype);   // 1 + 2\n  const result = Fn.apply(obj, args);        // 3\n  return (typeof result === \"object\" && result !== null) ? result : obj; // 4\n}\n\nfunction User(name) { this.name = name; }\nconst u = myNew(User, \"Amit\"); // same as new User(\"Amit\")" },
      { q: 'What are generator functions and how does yield work?', a: 'A function* is a special function that can PAUSE mid-execution at each yield and resume later exactly where it left off, instead of running start-to-finish in one go. Calling it returns an iterator, not the result — nothing runs until you call .next(), which runs until the next yield and returns { value, done }. Used to build custom iterables, lazy/infinite sequences, and (historically) to flatten async code before async/await existed (co, redux-saga).', code: "function* idGenerator() {\n  let id = 1;\n  while (true) yield id++;   // pauses here each time\n}\n\nconst gen = idGenerator();\ngen.next().value; // 1\ngen.next().value; // 2\ngen.next().value; // 3 - infinite, but lazy - only computes what you ask for" },
      { q: 'Explain the Symbol.iterator protocol — how do you make an object iterable with for...of?', a: 'for...of, spread (...), and destructuring all work on anything with a Symbol.iterator method that returns an iterator (an object with .next() returning { value, done }). Arrays, Strings, Maps, and Sets have it built in; plain objects don\'t, which is why for...of {} throws "is not iterable" — you must add Symbol.iterator yourself (often by delegating to a generator with yield*).', code: "const range = {\n  from: 1, to: 3,\n  [Symbol.iterator]() {\n    let current = this.from, last = this.to;\n    return { next: () => current <= last ? { value: current++, done: false } : { value: undefined, done: true } };\n  },\n};\n\nfor (const n of range) console.log(n); // 1, 2, 3\n[...range]; // [1, 2, 3] - spread uses the same protocol" },
      { q: 'What is a Proxy in JavaScript, and what is it used for?', a: 'A Proxy wraps a target object and lets you intercept fundamental operations on it (get, set, has, deleteProperty, ...) via "traps". It powers Vue 3\'s reactivity (detecting property reads/writes to know what to re-render), validation layers, negative array indices, and API objects that auto-create nested paths. Reflect is its companion — the default, correct way to forward an operation to the target inside a trap.', code: "const user = { name: \"Amit\" };\n\nconst logged = new Proxy(user, {\n  get(target, prop) {\n    console.log(\"read\", prop);\n    return Reflect.get(target, prop); // forward to the real object\n  },\n  set(target, prop, value) {\n    console.log(\"write\", prop, value);\n    return Reflect.set(target, prop, value);\n  },\n});\n\nlogged.name;          // logs \"read name\"\nlogged.name = \"Rahul\"; // logs \"write name Rahul\"" },
      { q: 'What is a WeakMap/WeakSet, and why use them over Map/Set?', a: 'WeakMap/WeakSet hold their keys (WeakMap) or values (WeakSet) WEAKLY — if nothing else references that object, the garbage collector can reclaim it even though the WeakMap still "has" it, preventing memory leaks. The trade-off: keys/values must be objects (no primitives), and they are NOT iterable (no .size, no for...of) because entries can vanish at any time. Classic use: attaching private/extra data to an object (e.g. a DOM node) without stopping it from being garbage collected once removed from the page.', code: "const cache = new WeakMap();\n\nfunction process(el) {\n  if (cache.has(el)) return cache.get(el);\n  const result = expensiveCompute(el);\n  cache.set(el, result); // if `el` is later removed from the DOM and has\n  return result;         // no other refs, it (and this entry) can be GC'd\n}" },
      { q: 'Difference between CommonJS (require) and ES Modules (import)?', a: 'CommonJS (Node\'s original system) loads modules SYNCHRONOUSLY at runtime — require() can be called conditionally/anywhere, and it exports a mutable module.exports object (a live copy-by-value snapshot at require time). ES Modules are STATIC — import/export must be top-level (enables tree-shaking, since bundlers can see the whole dependency graph without running code) and are loaded asynchronously, with live bindings (an imported value updates automatically if the source module changes it). Node supports both today (.cjs/.mjs or "type" in package.json), but mixing them (require("esm-only-pkg")) can fail.', code: "// CommonJS\nconst { readFile } = require(\"fs\");\nmodule.exports = { greet };\n\n// ES Modules\nimport { readFile } from \"fs\";\nexport function greet() {}\nexport default App;" },
      { q: 'Event loop OUTPUT question — what is the order of logs?', a: 'Interviewers care about the order, not the definition. Rule: run all synchronous code first; then drain the entire microtask queue (promise .then callbacks, code after await, queueMicrotask); only then take ONE macrotask (setTimeout, setInterval, I/O) and repeat. Note that an async function runs synchronously until its first await — only the code AFTER the await becomes a microtask.', code: "console.log('1');\nsetTimeout(() => console.log('2'), 0);          // macrotask\nPromise.resolve().then(() => console.log('3')); // microtask\n(async () => {\n  console.log('4');   // sync - async fn runs synchronously up to the first await\n  await null;\n  console.log('5');   // microtask\n})();\nconsole.log('6');\n// Output: 1 4 6 3 5 2" },
    ],
  },
  {
    title: 'React Deep Dive',
    items: [
      { q: 'Are setState calls batched in React 18?', a: 'Yes. Batching = grouping several state updates that happen in the same tick into ONE re-render. React 17 only batched inside React event handlers; React 18 (with createRoot) also batches inside setTimeout, promises/await, and native listeners. If you ever need to opt out for one update, use flushSync. This is also why setState is "async" — you will not see the new value on the next line.' },
      { q: 'Why does using the array index as a key break things when a list reorders?', a: 'React matches old and new list items by key; with index as key, reordering makes React think items merely changed content instead of moved, causing stale state or incorrect DOM updates in items like inputs. Use a stable unique id instead.', code: "// Bad: index as key when list can reorder\n{items.map((item, i) => <Row key={i} {...item} />)}\n\n// Good: stable unique id as key\n{items.map((item) => <Row key={item.id} {...item} />)}" },
      { q: 'What are useTransition and useDeferredValue, and how do they enable concurrent rendering?', a: 'Both let you mark work as LOW priority so React can interrupt it for something more urgent (a keystroke), keeping the UI responsive during expensive updates. useTransition wraps a state UPDATE: setState calls inside startTransition are non-urgent, and isPending tells you it is still working. useDeferredValue instead wraps a VALUE you already have, giving you a "lagging" copy that updates only once React has spare time — useful when you cannot control the setState call itself (e.g. a value from a parent/store).', code: "const [isPending, startTransition] = useTransition();\nconst [query, setQuery] = useState(\"\");\n\nfunction onChange(e) {\n  setQuery(e.target.value);            // urgent - input stays snappy\n  startTransition(() => {\n    setResults(filterHugeList(e.target.value)); // low priority\n  });\n}\n\n// useDeferredValue - same idea, for a value you don't setState yourself\nconst deferredQuery = useDeferredValue(query);\nconst results = useMemo(() => filterHugeList(deferredQuery), [deferredQuery]);" },
      { q: 'How does Suspense for data fetching work, and how is it different from Suspense for lazy()?', a: 'React.lazy() + Suspense was the first use case: a component "suspends" (throws a special promise) while its code chunk downloads, and Suspense shows a fallback until it resolves. Modern data-fetching frameworks (Next.js App Router, React Query with the suspense option, use()) extend the same mechanism to DATA: a component reading not-yet-loaded data throws a promise, the nearest <Suspense> boundary catches it and shows fallback, then re-renders the tree once the promise resolves. This lets you colocate data-dependent components without manual isLoading checks scattered everywhere, and multiple children can suspend independently under separate boundaries for progressive/streamed loading.', code: "<Suspense fallback={<Skeleton />}>\n  <UserProfile userId={id} />      {/* suspends until user data resolves */}\n</Suspense>\n\n// App Router - Server Components can be async directly:\nexport default async function UserProfile({ userId }) {\n  const user = await db.user.findById(userId); // Suspense boundary handles the wait\n  return <Profile user={user} />;\n}" },
      { q: 'What is useSyncExternalStore, and why does it exist?', a: 'A hook purpose-built for subscribing a component to state that lives OUTSIDE React (a global store like Redux/Zustand, browser APIs like window.innerWidth, a WebSocket). Before it, external subscriptions built with useState + useEffect could tear — show inconsistent values across components during a concurrent render, because React might render at two different times with two different snapshots. useSyncExternalStore guarantees a consistent snapshot across the whole tree during concurrent rendering; it is the primitive that libraries like Zustand and Redux use under the hood.', code: "function useWindowWidth() {\n  return useSyncExternalStore(\n    (callback) => {                          // subscribe\n      window.addEventListener(\"resize\", callback);\n      return () => window.removeEventListener(\"resize\", callback);\n    },\n    () => window.innerWidth,                  // getSnapshot (client)\n    () => 1024                                 // getServerSnapshot (SSR fallback)\n  );\n}" },
      { q: 'What causes a hydration mismatch error in Next.js/SSR, and how do you fix it?', a: 'SSR renders HTML on the server, then React "hydrates" it on the client by re-rendering and attaching event listeners — it expects the client render to produce IDENTICAL markup to what the server sent. A mismatch happens when the output differs between environments: using Date.now()/Math.random() during render, reading window/localStorage directly in render (undefined on the server), locale/timezone differences, or browser extensions injecting DOM before hydration. Fix by moving environment-specific reads into useEffect (so they run client-only, after hydration) or gating the dynamic part behind a mounted state flag, and use suppressHydrationWarning sparingly for genuinely unavoidable cases like timestamps.', code: "// broken - different value on server vs client\nfunction Clock() { return <span>{new Date().toLocaleTimeString()}</span>; }\n\n// fixed - render nothing (or a placeholder) until mounted client-side\nfunction Clock() {\n  const [time, setTime] = useState(null);\n  useEffect(() => setTime(new Date().toLocaleTimeString()), []);\n  return <span>{time ?? \"--:--:--\"}</span>;\n}" },
      { q: 'What is the compound components pattern?', a: 'A set of components designed to be used together, sharing implicit state via Context instead of the parent manually wiring props to each child — e.g. <Select><Select.Option/></Select> or <Tabs><Tabs.List/><Tabs.Panel/></Tabs>. It gives consumers full control over markup/order/styling while the parent still coordinates behavior (which tab is active), avoiding both prop-drilling and a rigid single monolithic component with dozens of config props.', code: "const TabsContext = createContext();\n\nfunction Tabs({ children }) {\n  const [active, setActive] = useState(0);\n  return <TabsContext.Provider value={{ active, setActive }}>{children}</TabsContext.Provider>;\n}\nTabs.Tab = function Tab({ index, children }) {\n  const { active, setActive } = useContext(TabsContext);\n  return <button onClick={() => setActive(index)} aria-selected={active === index}>{children}</button>;\n};\n\n<Tabs><Tabs.Tab index={0}>Profile</Tabs.Tab><Tabs.Tab index={1}>Settings</Tabs.Tab></Tabs>;" },
      { q: 'What are Server Actions in Next.js, and how do they differ from a normal API route?', a: 'A Server Action is an async function marked "use server" that you can call DIRECTLY from a component (including from a <form action={...}>) as if it were local — Next.js generates the network call, serialization, and endpoint for you. Unlike a hand-written API route, there is no need to define a URL, parse the request body, or write a matching fetch() call on the client; it also integrates with useFormStatus/useOptimistic for pending/optimistic UI, and revalidatePath/revalidateTag to refresh cached data after a mutation. Still runs server-side only — treat its input as untrusted and validate it, same as any API route.', code: "// app/actions.ts\n\"use server\";\nexport async function createPost(formData: FormData) {\n  const title = formData.get(\"title\");\n  await db.post.create({ data: { title } });\n  revalidatePath(\"/posts\");\n}\n\n// component - no fetch, no API route needed\n<form action={createPost}>\n  <input name=\"title\" />\n  <button type=\"submit\">Create</button>\n</form>" },
      { q: 'Your API fires twice in useEffect — is it Strict Mode or a real bug?', a: "In development, StrictMode intentionally mounts → unmounts → re-mounts every component to surface effects that lack cleanup, so effects (and the fetch) run twice — in dev only. Quick check: build for production; if the double call disappears it was Strict Mode. It is a REAL bug if it also happens in production: unstable dependencies (an object/array/function recreated every render), the parent re-mounting the component (changing key, conditional rendering), an effect that sets state which is in its own deps (loop), or two components fetching the same data. Fix the cause — don't remove StrictMode: add cleanup (AbortController / ignore flag), memoize or lift unstable deps, and use React Query/SWR to dedupe requests.", code: "useEffect(() => {\n  const controller = new AbortController();\n  fetch('/api/products', { signal: controller.signal })\n    .then((r) => r.json())\n    .then(setProducts)\n    .catch((e) => { if (e.name !== 'AbortError') setError(e); });\n  return () => controller.abort(); // cleanup makes the double-run harmless\n}, []);" },
      { q: "Why does wrapping an input's state update in startTransition make typing lag?", a: "startTransition marks an update as LOW priority — React may delay or interrupt it. A controlled input's value must update immediately (urgent), so if setValue itself is inside startTransition, the input shows stale text and typing feels laggy or drops characters. Correct pattern: keep the input state urgent, and put only the EXPENSIVE derived update (filtering a big list) inside the transition — or use useDeferredValue on the value that feeds the heavy list.", code: "const [text, setText] = useState('');      // urgent - drives the input\nconst [query, setQuery] = useState('');    // deferred - drives the heavy list\n\nfunction onChange(e) {\n  setText(e.target.value);                  // NOT inside startTransition\n  startTransition(() => setQuery(e.target.value));\n}\n\n// or: const deferredText = useDeferredValue(text); and filter with deferredText" },
      { q: 'What is React Compiler, and what does it skip?', a: "React Compiler is a build-time (Babel/SWC plugin) tool that auto-memoizes components and hooks, so you rarely need to hand-write useMemo/useCallback/React.memo — it caches values and skips re-renders at a finer granularity than manual memoization. It only works on code that follows the Rules of React, so it silently BAILS OUT (skips that component/hook, the rest still compiles) when it sees things like: mutating props/state/values during render, reading or writing ref.current during render, impure/non-idempotent render logic, hooks called conditionally, or class components. You can opt a component out with the 'use no memo' directive, and eslint-plugin-react-compiler flags what it can't handle. It doesn't replace fixing slow algorithms or virtualizing huge lists." },
      { q: 'RSC vs SSR — are they the same thing?', a: "No. SSR renders components to HTML on the server so the user sees content quickly, but the JavaScript for those components is still shipped to the browser and hydrated. React Server Components run ONLY on the server and their JS is never sent to the client — the result is a serialized component tree (RSC payload) merged into the client tree. They can read the DB/filesystem directly and need no hydration, but can't use state, effects or browser APIs. They are complementary: in the Next.js App Router, Server Components reduce the client bundle, while both Server and Client Components are also SSR'd to HTML for the first paint (Client Components are then hydrated)." },
      { q: 'What is Redux Thunk, and how does createAsyncThunk relate to it?', a: 'Thunk is Redux middleware that lets an action creator return a FUNCTION (receiving dispatch and getState) instead of a plain object, so you can run async logic — fetch, then dispatch results. Redux Toolkit includes it by default. createAsyncThunk wraps the pattern: you give it a payload creator and it auto-dispatches pending / fulfilled / rejected actions that you handle in extraReducers.', code: "export const fetchUsers = createAsyncThunk('users/fetch', async (_, { rejectWithValue }) => {\n  try {\n    const res = await fetch('/api/users');\n    return await res.json();\n  } catch (e) {\n    return rejectWithValue(e.message);\n  }\n});\n\nconst usersSlice = createSlice({\n  name: 'users',\n  initialState: { list: [], status: 'idle', error: null },\n  reducers: {},\n  extraReducers: (b) => {\n    b.addCase(fetchUsers.pending, (s) => { s.status = 'loading'; })\n     .addCase(fetchUsers.fulfilled, (s, a) => { s.status = 'succeeded'; s.list = a.payload; })\n     .addCase(fetchUsers.rejected, (s, a) => { s.status = 'failed'; s.error = a.payload; });\n  },\n});" },
      { q: 'How do you design client-side caching, API retries, and error boundaries gracefully?', a: "Caching: use React Query/SWR — stale-while-revalidate keyed by query key, so repeat views are instant and background refetch keeps data fresh. Retries: retry only network errors and 5xx/429 (never 4xx), with exponential backoff + jitter and a max attempt cap; add timeouts and AbortController so stale requests are cancelled. Errors: put Error Boundaries at route and widget level with a fallback UI and a reset/retry button so one failing widget doesn't blank the page. Remember boundaries do NOT catch async errors or event-handler errors — surface those through the query's error state/toasts. Report everything to a monitoring tool (Sentry)." },
      { q: 'How do you manage global state efficiently when multiple teams contribute to one React app?', a: "Don't make everything global — classify state: server data → React Query/SWR; URL state (filters, page) → the router; local UI state → useState/useReducer; only truly shared client state (auth, theme, cart) → a small store like Redux Toolkit or Zustand. Split the store into feature slices, each owned by one team, exposing a public API of typed selectors/actions; forbid cross-slice imports via lint rules and CODEOWNERS; keep conventions documented. Avoid Context for frequently-changing values (it re-renders all consumers)." },
    ],
  },
  {
    title: 'Machine Coding Round',
    items: [
      { q: 'Nested File/Folder Explorer — how do you approach it?', a: 'One recursive component that renders a file as a leaf and a folder as a name + its children mapped through the same component. Each folder owns its expand/collapse state locally (useState), so it handles infinite nesting with no depth logic. What they test: recursion, local state, clean modular component structure.' },
      { q: 'Autocomplete / typeahead search — key points?', a: 'Debounce the input (~300ms), ignore stale responses (track the latest query or use AbortController), cache results per query, support keyboard nav (arrow keys + Enter + Esc), show loading/empty/error states, and close on outside click. What they test: debouncing, race conditions, accessibility.' },
      { q: 'Nested comments (threaded replies) — how do you build it?', a: 'Recursive <Comment> component; store comments as a tree, or as a flat list with parentId and build the tree with a map. Each comment has its own reply-box toggle state, and adding a reply updates state immutably at the right node. What they test: recursion, immutable nested updates, keys.' },
      { q: 'Star rating component — what do interviewers look for?', a: 'Controlled component (value + onChange), a hover-preview state separate from the committed value, keyboard support (arrow keys), optional half-star handling, and aria-label per star with role="radiogroup". Small task, but they watch for controlled state and accessibility.' },
      { q: 'What state-management mistakes fail a machine coding round?', a: 'Mutating state directly, deriving state that should just be computed during render, lifting state higher than needed, using array index as key in a reorderable list, and putting everything in one giant component instead of small focused ones.' },
      { q: 'Sequential progress bars (Add button, one fills at a time, clicks queue) — how do you build it?', a: "Model the bars as an array of progress numbers. The 'active' bar is simply the FIRST one below 100 — derive it, don't store it. One effect ticks only the active bar (2s ≈ 20 ticks × 100ms). When it reaches 100, activeIndex changes, the effect re-runs and the next bar starts automatically, which gives you the queue for free. Clicking Add just appends a 0. Key points to mention: derived state instead of a separate 'current' variable, interval cleanup, and functional setState so ticks never read stale state.", code: "function Bars() {\n  const [bars, setBars] = useState([]);           // each value is 0-100\n  const active = bars.findIndex((p) => p < 100);   // derived, first unfinished bar\n\n  useEffect(() => {\n    if (active === -1) return;\n    const id = setInterval(() => {\n      setBars((prev) => prev.map((p, i) => (i === active ? Math.min(p + 5, 100) : p)));\n    }, 100);                                        // 20 ticks x 100ms = 2s\n    return () => clearInterval(id);\n  }, [active]);\n\n  return (\n    <>\n      <button onClick={() => setBars((b) => [...b, 0])}>Add</button>\n      {bars.map((p, i) => (\n        <div key={i} className=\"track\"><div className=\"fill\" style={{ width: `${p}%` }} /></div>\n      ))}\n    </>\n  );\n}" },
      { q: 'Nested checkbox tree with indeterminate parents — how do you approach it?', a: "Keep ONE source of truth: a Set of checked LEAF ids. A parent's state is derived from its leaves — all checked → checked, none → unchecked, some → indeterminate. Toggling a parent adds/removes all its descendant leaves at once. 'indeterminate' is a DOM property, not an HTML attribute, so set it through a ref in an effect. Storing checked state on every node instead leads to sync bugs between parent and children.", code: "const leaves = (n) => (n.children ? n.children.flatMap(leaves) : [n.id]);\n\nfunction Node({ node, checked, toggle }) {\n  const ids = leaves(node);\n  const count = ids.filter((id) => checked.has(id)).length;\n  const all = count === ids.length;\n  const some = count > 0 && !all;\n  const ref = useRef(null);\n  useEffect(() => { ref.current.indeterminate = some; }, [some]);\n\n  return (\n    <li>\n      <label>\n        <input ref={ref} type=\"checkbox\" checked={all} onChange={() => toggle(ids, !all)} />\n        {node.label}\n      </label>\n      {node.children && (\n        <ul>{node.children.map((c) => <Node key={c.id} node={c} checked={checked} toggle={toggle} />)}</ul>\n      )}\n    </li>\n  );\n}\n\n// in the parent component\nconst toggle = (ids, on) =>\n  setChecked((prev) => {\n    const next = new Set(prev);\n    ids.forEach((id) => (on ? next.add(id) : next.delete(id)));\n    return next;\n  });" },
      { q: 'OTP input with auto-focus and paste-split — key points?', a: "Use an array of refs, one box per digit. onChange: accept a single digit only, then focus the next box. onKeyDown Backspace on an empty box: focus the previous one. onPaste: preventDefault, strip non-digits from clipboardData, slice to the OTP length, fill all boxes at once and focus the last filled box. Also set inputMode='numeric' and autoComplete='one-time-code' (enables SMS autofill) and give each box an aria-label ('Digit 1 of 6').", code: "const onPaste = (e) => {\n  e.preventDefault();\n  const digits = e.clipboardData.getData('text').replace(/\\D/g, '').slice(0, LEN);\n  setOtp(Array.from({ length: LEN }, (_, i) => digits[i] ?? ''));\n  refs.current[Math.min(digits.length, LEN - 1)]?.focus();\n};" },
      { q: 'Client-side pagination from an API (loading, error, page navigation) — what do interviewers check?', a: "They check that the UI reflects EVERY API state: a loading indicator (and disabled Prev/Next while loading), an error state with a Retry button, and an empty state. Keep page in state and refetch in an effect keyed on page. Handle stale responses with AbortController (or an ignore flag) so a slow page-1 response can't overwrite page 2. Disable Prev on page 1 and Next on the last page (use total count or an empty result), and ideally keep the previous data visible while the next page loads to avoid flicker. Mention that React Query's keepPreviousData does all of this." },
    ],
  },
  {
    title: 'Node.js / Backend Deep Dive',
    items: [
      { q: 'What are the phases of the Node.js event loop?', a: 'Each loop turn runs these phases in order: timers (due setTimeout/setInterval callbacks) -> pending callbacks (some deferred system ops) -> poll (wait for and run I/O callbacks — the main phase) -> check (setImmediate callbacks) -> close callbacks (e.g. socket "close"). Between EVERY phase, Node fully drains the process.nextTick queue and then the Promise microtask queue — which is why a .then always runs before the next timer.' },
      { q: 'What are the core principles of good REST API design?', a: 'Model URLs as resources (nouns): /users/123/orders, not /getUserOrders. Use HTTP verbs for the action (GET/POST/PUT/PATCH/DELETE) and return the right status code. Keep it stateless — every request carries its own auth. Validate and sanitise all input server-side (never trust the client). Paginate list endpoints. Version the API (/v1). Return a consistent error shape. Make writes idempotent where possible so retries are safe.' },
      { q: 'What happens internally when a request hits a Node.js API? (Event Loop + Call Stack)', a: "The OS receives the TCP connection and libuv's event loop picks it up in the poll phase. Node's HTTP parser builds req/res and your Express handler is pushed onto the call stack and runs synchronously until it hits async work (DB query, fs, fetch). That work is handed to the OS (network I/O via epoll/kqueue) or to libuv's thread pool (fs, crypto, dns), the handler returns, and the call stack empties — so Node is free to serve other requests. When the work finishes its callback is queued; the event loop moves it onto the call stack once it is empty (microtasks — promise continuations and process.nextTick — run first). Finally res.send() writes the response. The key point: your JS runs on ONE thread, but waiting for I/O never blocks it.", code: "app.get('/user', async (req, res) => {\n  console.log('1 handler starts');        // call stack\n  const user = await db.findUser();       // handed off; stack empties here\n  console.log('3 back after I/O');        // callback resumes via microtask\n  res.json(user);\n});\nconsole.log('2 server keeps serving other requests');" },
      { q: 'How does Node.js handle multiple requests if it is single-threaded?', a: "Node runs your JavaScript on one thread, but I/O is non-blocking: network and disk work is delegated to the OS or libuv's thread pool (default 4 threads), and the thread moves on to the next request while waiting. So it gives concurrency (many requests in flight), not parallelism (many JS lines executing at once). It scales well for I/O-bound APIs, but a CPU-heavy or synchronous operation (big JSON.parse, crypto loop, sync fs) blocks EVERY request. To use multiple cores you run several processes — cluster/PM2 or containers behind a load balancer." },
      { q: 'How do you handle CPU-intensive tasks in Node.js without blocking the event loop?', a: 'Move the work off the main thread: (1) worker_threads for in-process parallel CPU work (image processing, hashing, parsing); (2) push a job to a queue (BullMQ/RabbitMQ/Kafka) and let a separate worker service process it, returning a job id to the client; (3) child_process / a service in another language for very heavy jobs; (4) for small loops, split the work into chunks and yield with setImmediate so I/O can interleave. Never run heavy sync code inside a request handler.', code: "// main.js\nconst { Worker } = require('worker_threads');\napp.get('/report', (req, res) => {\n  const worker = new Worker('./heavy.js', { workerData: req.query });\n  worker.on('message', (result) => res.json(result));\n  worker.on('error', (err) => res.status(500).json({ error: err.message }));\n});\n\n// heavy.js\nconst { parentPort, workerData } = require('worker_threads');\nparentPort.postMessage(doExpensiveWork(workerData));" },
      { q: 'How would you design a scalable backend to handle 10K+ requests per second?', a: 'Remove bottlenecks layer by layer: (1) run many STATELESS Node instances (cluster/containers) behind a load balancer with auto-scaling — if one instance handles ~1K rps, you need 10+ with headroom; (2) cache aggressively — CDN for static/public data, Redis for hot reads; (3) database — right indexes, connection pooling, read replicas, later sharding; (4) push slow/non-critical work (emails, reports, webhooks) to a queue (Kafka/RabbitMQ) with background workers; (5) protect the system — rate limiting, timeouts, circuit breakers, pagination, compression; (6) observability — logs, metrics, tracing, alerts; (7) load-test (k6/Artillery) to find the real bottleneck instead of guessing. Scaling is finding and removing bottlenecks, not just adding servers.' },
      { q: 'How do you optimize slow MongoDB queries in a Node.js app?', a: "First measure: enable the profiler / slow query log and run .explain('executionStats') — a COLLSCAN or docsExamined far greater than nReturned means a missing or wrong index. Then: add compound indexes following the ESR rule (Equality fields first, then Sort, then Range); use projection to return only needed fields; use .lean() in Mongoose to skip document hydration; replace deep skip() pagination with cursor/keyset pagination; put $match and $limit early in aggregation pipelines; avoid heavy $lookup by embedding or denormalizing hot data; cache repeated reads in Redis; and keep the connection pool sized properly. Re-run explain after each change to confirm the win.", code: "db.orders.find({ userId: 42, status: 'paid' }).sort({ createdAt: -1 }).explain('executionStats');\n// look at: stage (COLLSCAN vs IXSCAN), totalDocsExamined vs nReturned\n\ndb.orders.createIndex({ userId: 1, status: 1, createdAt: -1 }); // Equality, Equality, Sort" },
    ],
  },
  {
    title: 'Git / Docker / Testing / Deployment',
    items: [
      { q: 'What are git stash and git cherry-pick used for?', a: 'git stash temporarily shelves uncommitted changes so you can switch branches cleanly, then reapplies them later. git cherry-pick applies one specific commit from another branch without merging the whole branch.', code: "git stash                 # shelve uncommitted changes\ngit checkout other-branch\ngit stash pop              # reapply them later\n\ngit cherry-pick <commit-sha> # apply one commit onto the current branch" },
      { q: 'Why use multi-stage builds in Docker?', a: 'To keep the final production image small — build/compile in an early stage with all dev dependencies, then copy only the built output into a lean final stage, discarding build tools and source.', code: "FROM node:20 AS build\nWORKDIR /app\nCOPY . .\nRUN npm install && npm run build\n\nFROM node:20-alpine\nCOPY --from=build /app/dist ./dist\nCMD [\"node\", \"dist/index.js\"]\n# final image has no dev deps or source, just the build output" },
      { q: 'What do you typically use to test React components?', a: 'Jest + React Testing Library — render the component, query elements the way a user would (getByText/getByRole), simulate interaction with fireEvent/userEvent, and assert on the resulting UI state.', code: "import { render, screen, fireEvent } from \"@testing-library/react\";\n\ntest(\"increments count on button click\", () => {\n  render(<Counter />);\n  fireEvent.click(screen.getByText(\"+\"));\n  expect(screen.getByText(\"1\")).toBeInTheDocument();\n});" },
      { q: 'What does a typical Next.js deployment on Vercel look like?', a: 'Zero-config deploys straight from a Git repo, automatic preview deployments per PR, and edge functions for low-latency middleware/API routes, with secrets kept out of the repo via environment variables and the platform\'s secret manager.' },
    ],
  },
  {
    title: 'Git — Commands & Workflows',
    items: [
      { q: 'git init vs git clone?', a: 'git init creates a brand-new empty repository in the current folder. git clone <url> copies an existing remote repository (all history + branches) and wires up "origin" automatically.', code: "git init\ngit clone https://github.com/user/repo.git\ngit clone git@github.com:user/repo.git my-folder" },
      { q: 'What does git status show?', a: 'The current branch, which files are staged, which are modified but unstaged, and which are untracked — plus how far ahead/behind you are from the upstream branch.', code: "git status\ngit status -s   # short format" },
      { q: 'How does git add work (staging)?', a: 'It moves changes into the staging area (index) so the next commit includes them. Use a path for one file, . for everything, or -p to stage selected hunks interactively.', code: "git add file.js\ngit add .\ngit add -p        # pick hunks to stage\ngit restore --staged file.js   # unstage" },
      { q: 'git commit — the common forms?', a: '-m sets the message inline, -a auto-stages already-tracked files (not new ones), and --amend rewrites the last commit (message and/or contents). Never --amend a commit that\'s already pushed and shared.', code: "git commit -m \"feat: add search\"\ngit commit -am \"fix: typo\"           # stage tracked + commit\ngit commit --amend -m \"better message\"\ngit commit --amend --no-edit          # add staged changes to last commit" },
      { q: 'How do you read history with git log?', a: 'Plain git log is verbose; --oneline compresses each commit to one line, --graph draws branch/merge structure, -p shows the diff per commit, and --stat shows changed-file summaries.', code: "git log --oneline --graph --decorate --all\ngit log -p file.js        # history of one file with diffs\ngit log --stat -3         # last 3 commits, file summary" },
      { q: 'git diff — what are you comparing?', a: 'By default: working tree vs staging. --staged (or --cached): staging vs last commit. git diff HEAD: everything since the last commit. You can also diff two branches or commits.', code: "git diff                 # unstaged changes\ngit diff --staged        # staged changes\ngit diff HEAD            # all uncommitted changes\ngit diff main..feature   # branch vs branch" },
      { q: 'git branch — create, list, delete, rename?', a: 'git branch lists branches; git branch <name> creates one (without switching); -d deletes a merged branch, -D force-deletes; -m renames the current branch.', code: "git branch\ngit branch feature/login\ngit branch -d old-feature      # safe delete (merged only)\ngit branch -D broken-feature   # force delete\ngit branch -m new-name         # rename current branch" },
      { q: 'git checkout vs git switch vs git restore?', a: 'Old git checkout was overloaded (switch branches AND discard files). Modern git splits it: git switch changes branches, git restore discards/unstages file changes. checkout still works but switch/restore are clearer.', code: "git switch main\ngit switch -c feature/x        # create + switch\ngit restore file.js           # discard working changes\ngit restore --source=HEAD~2 file.js" },
      { q: 'git merge — fast-forward vs merge commit?', a: 'If the target branch hasn\'t diverged, git just moves the pointer forward (fast-forward, no new commit). If both branches have new commits, git creates a merge commit tying them together. --no-ff forces a merge commit even when a fast-forward is possible; --squash flattens all the branch\'s changes into one uncommitted change set.', code: "git merge feature/login\ngit merge --no-ff feature/login   # always create a merge commit\ngit merge --squash feature/login  # combine into one commit\ngit merge --abort                 # bail out of a conflicted merge" },
      { q: 'git rebase — what does it actually do?', a: 'It takes your branch\'s commits, temporarily removes them, updates the branch to the target tip, then re-applies your commits one by one on top — giving a linear history with no merge commits. Rewrites commit hashes, so never rebase commits that are already pushed and shared.', code: "git switch feature\ngit rebase main            # replay feature\'s commits on top of main\ngit rebase --continue      # after resolving a conflict\ngit rebase --abort         # undo the whole rebase\ngit rebase --skip          # drop the conflicting commit" },
      { q: 'What is interactive rebase (git rebase -i)?', a: 'Opens an editor listing recent commits so you can reword, squash/fixup (combine), drop, edit, or reorder them before they\'re re-applied — the standard way to clean up a messy branch before opening a PR.', code: "git rebase -i HEAD~4\n# pick   <hash> first commit\n# squash <hash> fold into previous\n# reword <hash> change message\n# drop   <hash> remove commit" },
      { q: 'git fetch vs git pull?', a: 'git fetch downloads new commits/branches from the remote but does NOT touch your working branch — you inspect, then merge/rebase yourself. git pull = git fetch + an automatic integrate (merge by default) of the upstream branch into your current one.', code: "git fetch origin\ngit log HEAD..origin/main   # see what you\'d be pulling\ngit pull" },
      { q: 'git pull --rebase vs git pull --no-rebase?', a: '--no-rebase (the classic default) does fetch + merge, creating a merge commit when your local branch has commits the remote doesn\'t. --rebase does fetch + rebase, replaying your local commits on top of the updated remote for a linear history. --ff-only refuses to do either and fails if a fast-forward isn\'t possible.', code: "git pull --no-rebase     # fetch + merge (merge commit if diverged)\ngit pull --rebase        # fetch + rebase your commits on top\ngit pull --ff-only       # only if it can fast-forward, else abort\n\ngit config pull.rebase false   # make --no-rebase the default\ngit config pull.rebase true    # make --rebase the default\ngit config pull.ff only        # make --ff-only the default" },
      { q: 'When do you specifically want git pull --no-rebase?', a: 'On a shared branch where you want to preserve the true history and see exactly when integration happened (the merge commit), or when your local commits are already pushed/shared so rebasing them would rewrite public history. It\'s the safe choice when in doubt.', code: "git pull --no-rebase origin main\n# keeps your local commits as-is, adds a merge commit:\n#   *   Merge branch \'main\' of origin\n#   |\\\n#   | * origin commits\n#   * | your local commits" },
      { q: 'git push — the flags you actually use?', a: '-u (--set-upstream) links your local branch to a remote one on the first push. --force-with-lease safely overwrites the remote after a rebase/amend (fails if someone else pushed in between) — prefer it over --force. Pushing a deletion removes a remote branch.', code: "git push -u origin feature/login   # first push, sets upstream\ngit push                            # subsequent pushes\ngit push --force-with-lease         # after rebase/amend (safe force)\ngit push origin --delete old-branch # delete a remote branch" },
      { q: 'git remote — inspecting and changing remotes?', a: 'git remote -v lists remote names + URLs. add registers a new remote (e.g. "upstream" for a fork), set-url changes an existing one (e.g. HTTPS to SSH), remove deletes it.', code: "git remote -v\ngit remote add upstream https://github.com/org/repo.git\ngit remote set-url origin git@github.com:me/repo.git\ngit remote remove upstream" },
      { q: 'git stash — the full workflow?', a: 'Shelves uncommitted changes (tracked by default; -u also includes untracked) so your working tree is clean. list shows the stack, pop applies + removes the top, apply applies but keeps it, drop discards one.', code: "git stash push -m \"wip: half-done form\"\ngit stash -u                 # include untracked files\ngit stash list\ngit stash pop                # apply + remove newest\ngit stash apply stash@{2}    # apply a specific one, keep it\ngit stash drop stash@{0}\ngit stash clear              # remove all" },
      { q: 'git cherry-pick — picking specific commits?', a: 'Applies the changes from one or more specific commits onto your current branch, creating new commits — useful for pulling a hotfix from another branch without merging everything. Supports ranges and conflict resolution like a mini-rebase.', code: "git cherry-pick <hash>\ngit cherry-pick <hash1> <hash2>\ngit cherry-pick A..B          # range (A exclusive .. B inclusive)\ngit cherry-pick --continue    # after resolving conflicts\ngit cherry-pick --abort" },
      { q: 'git reset --soft / --mixed / --hard?', a: 'All move the branch pointer to a target commit. --soft keeps changes staged. --mixed (default) keeps changes but unstaged. --hard discards changes entirely (destructive). Reset is for local history only — use revert on shared branches.', code: "git reset --soft HEAD~1    # undo last commit, keep changes staged\ngit reset HEAD~1           # undo last commit, keep changes unstaged\ngit reset --hard HEAD~1    # undo last commit AND discard changes\ngit reset HEAD file.js     # unstage a file (old syntax)" },
      { q: 'git revert vs git reset?', a: 'git revert creates a NEW commit that undoes a previous commit\'s changes, leaving history intact — safe on shared/pushed branches. git reset rewrites history by moving the branch pointer — only safe locally.', code: "git revert <hash>            # new commit that undoes <hash>\ngit revert HEAD             # undo the last commit safely\ngit revert --no-commit A..B  # stage the inverse of a range" },
      { q: 'git restore — discarding and unstaging?', a: 'git restore <file> throws away working-tree changes to that file. git restore --staged <file> unstages it (moves it back out of the index) without changing the file contents. --source lets you restore a file from any commit.', code: "git restore file.js               # discard local edits\ngit restore --staged file.js      # unstage (keep edits)\ngit restore .                     # discard ALL working changes\ngit restore --source=HEAD~3 file.js" },
      { q: 'Lightweight vs annotated git tags?', a: 'A lightweight tag is just a name pointing at a commit. An annotated tag (-a) is a full object with a message, tagger, and date — use annotated for releases. Tags aren\'t pushed by default.', code: "git tag v1.2.0                       # lightweight\ngit tag -a v1.2.0 -m \"Release 1.2.0\"  # annotated\ngit push origin v1.2.0\ngit push origin --tags\ngit tag -d v1.2.0                    # delete local tag" },
      { q: 'What does git apply do?', a: 'Applies a patch/diff file to your working tree WITHOUT creating a commit or recording authorship — it just changes the files. Use --check to dry-run, --3way to fall back to a 3-way merge on conflicts, -R to reverse-apply (undo) a patch.', code: "git diff > my.patch\ngit apply my.patch\ngit apply --check my.patch     # test if it applies cleanly\ngit apply --3way my.patch      # allow conflict markers on fuzz\ngit apply -R my.patch          # undo a previously applied patch" },
      { q: 'git apply vs git am vs git format-patch?', a: 'git format-patch turns commits into .patch files (one per commit, with author/message, mbox format). git am applies those and RECREATES the commits with original authorship. git apply only applies the raw diff, no commit. Use format-patch + am to move commits between repos by email/file.', code: "git format-patch -3            # last 3 commits -> 0001-*.patch ...\ngit format-patch main..feature\n\ngit am 0001-add-feature.patch  # apply as a real commit\ngit am --abort\ngit am --continue" },
      { q: 'git clean — removing untracked files?', a: 'Deletes files git isn\'t tracking (build output, junk). It\'s destructive and NOT undoable, so always dry-run with -n first. -f is required to actually delete, -d includes directories, -x also removes ignored files.', code: "git clean -n           # dry run: list what would be deleted\ngit clean -fd          # delete untracked files + dirs\ngit clean -fdx         # also delete .gitignore\'d files" },
      { q: 'What is git reflog and when does it save you?', a: 'A local log of every place HEAD has pointed — commits, resets, rebases, checkouts. Even after a bad git reset --hard or a botched rebase, the old commit is still in the reflog, so you can recover it.', code: "git reflog\n# a1b2c3d HEAD@{1}: reset: moving to HEAD~3\ngit reset --hard HEAD@{1}     # go back to before the reset\ngit branch recovered a1b2c3d # rescue a lost commit" },
      { q: 'How do you resolve a merge/rebase conflict?', a: 'Git marks conflicted regions with <<<<<<< ======= >>>>>>> in the files. Edit each file to the desired final content, remove the markers, git add the resolved files, then continue: git commit (merge) or git rebase --continue / git cherry-pick --continue. --abort backs out entirely.', code: "# 1. edit files, remove <<<<<<< / ======= / >>>>>>> markers\ngit add resolved-file.js\ngit rebase --continue   # or: git commit   (for a merge)\n\ngit merge --abort       # or git rebase --abort to bail" },
      { q: 'git bisect — finding the commit that broke something?', a: 'A binary search over history: you mark a known-good and known-bad commit, git checks out the midpoint, you test and mark good/bad, and it narrows down to the exact breaking commit in log2(n) steps.', code: "git bisect start\ngit bisect bad                # current commit is broken\ngit bisect good v1.0.0        # this old one worked\n# test, then: git bisect good  OR  git bisect bad\ngit bisect reset             # done, return to HEAD" },
      { q: 'git blame and git show?', a: 'git blame <file> shows, per line, the last commit + author that changed it — for tracking down why a line exists. git show <hash> displays a single commit\'s message and full diff.', code: "git blame src/app.js\ngit blame -L 40,60 src/app.js   # only lines 40-60\ngit show <hash>\ngit show HEAD~2:src/app.js      # a file as it was 2 commits ago" },
      { q: 'git rm and git mv?', a: 'git rm deletes a tracked file AND stages the deletion. --cached removes it from tracking but keeps it on disk (e.g. after adding it to .gitignore). git mv renames/moves a tracked file and stages that.', code: "git rm old.js\ngit rm --cached .env        # stop tracking, keep the file\ngit mv utils.js helpers.js" },
      { q: 'How does .gitignore work, and how do you untrack an already-committed file?', a: '.gitignore lists patterns git should not track — but it only affects untracked files. A file already committed keeps being tracked until you remove it with git rm --cached, then commit.', code: "echo \"node_modules/\" >> .gitignore\necho \".env\" >> .gitignore\ngit rm -r --cached node_modules .env\ngit commit -m \"chore: stop tracking node_modules and .env\"" },
      { q: 'What are HEAD and a detached HEAD?', a: 'HEAD is a pointer to your current commit — normally it points at a branch, which points at a commit. Detached HEAD means you checked out a specific commit/tag directly, so new commits belong to no branch and can be lost. Fix by creating a branch: git switch -c <name>.', code: "git checkout v1.0.0       # detached HEAD\ngit switch -c hotfix      # attach new work to a branch\ngit switch -               # back to previous branch" },
      { q: 'git config — identity, scope, and aliases?', a: 'git config sets options at --local (this repo), --global (your user), or --system scope. You must set user.name/user.email before committing. Aliases shorten frequent commands.', code: "git config --global user.name \"Rishabh Tiwari\"\ngit config --global user.email \"you@example.com\"\ngit config --local user.email \"work@company.com\"   # override per repo\n\ngit config --global alias.lg \"log --oneline --graph --all\"\ngit config --global alias.st status" },
      { q: 'git switch - and git checkout - ?', a: 'The dash is shorthand for "the previous branch you were on" — quick toggling between two branches without typing names.', code: "git switch -       # jump back to the last branch\ngit checkout -     # same thing (older syntax)" },
    ],
  },
];
